						local SuccessLocal, ValueLocal = pcall(EntryLocal.Get)
						if SuccessLocal then
							self.Defaults[FlagLocal] = ValueLocal
						end
					end
				end

				__A0Boot:Budget()
				function Library:ResetDefaults(IgnoreLocal)
					self:LoadConfig(self.Defaults, IgnoreLocal)
				end

				__A0Boot:Budget()
				local TrackCount = 0
				__A0Boot:Budget()
				local function Track(Conn)
					TrackCount = TrackCount + 1
					if TrackCount % 64 == 0 then
						for IndexLocal = #Library.Connections, 1, -1 do
							if not Library.Connections[IndexLocal].Connected then
								table.remove(Library.Connections, IndexLocal)
							end
						end
					end
					table.insert(Library.Connections, Conn)
					return Conn
				end

				__A0Boot:Budget()

				Library.SearchTargets = {}
				function Library:UnregisterSearchTarget(Argument, Expected)
					local EntryLocal = self.SearchTargets[Argument]
					if not EntryLocal or (Expected and EntryLocal ~= Expected) then
						return false
					end
					self.SearchTargets[Argument] = nil
					if EntryLocal.Connection then
						EntryLocal.Connection:Disconnect()
					end
					self.RegistryVersion = (self.RegistryVersion or 0) + 1
					return true
				end
				function Library:RegisterSearchTarget(Argument, TargetLocal)
					if
						self.Destroyed
						or type(TargetLocal) ~= "table"
						or not TargetLocal.Instance
						or not TargetLocal.Instance.Parent
					then
						return nil
					end
					self:UnregisterSearchTarget(Argument)
					local EntryLocal = {
						Label = tostring(TargetLocal.Label or Argument),
						Type = TargetLocal.Type or "Control",
						Instance = TargetLocal.Instance,
					}
					self.SearchTargets[Argument] = EntryLocal
					self.RegistryVersion = (self.RegistryVersion or 0) + 1
					EntryLocal.Connection = Track(EntryLocal.Instance.Destroying:Connect(function()
						self:UnregisterSearchTarget(Argument, EntryLocal)
					end))
					return EntryLocal
				end

