				function Library:Translate(TextLocal)
					if type(TextLocal) ~= "string" then
						return TextLocal
					end
					local Simple = ShortEnglishText[TextLocal] or TextLocal
					if self.Language == "Thai" then
						local PlaceFile = Simple:match("^Autosave file: (A0%d+%.json)$")
						if PlaceFile then
							return "ไฟล์บันทึกอัตโนมัติ: " .. PlaceFile
						end
						local SlotLocal = Simple:match("^Custom Speed Slot (%d+)")
						if SlotLocal then
							return "ช่องความเร็ว " .. SlotLocal
						end
						if TextLocal == "Lunge Modifier" or TextLocal:find("King's Scourge", 1, true) then
							return TextLocal
						end
						local Clean = Simple:gsub("^%s*•%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
						local Exact = ThaiText[TextLocal] or ThaiText[Simple] or ThaiText[Clean]
						if Exact then
							return Exact
						end
						local SlotNumber = Clean:match("^Slot (%d+)$")
						if SlotNumber then
							return "ช่องที่ " .. SlotNumber
						end
						local Prefix, SuffixLocal = Clean:match("^(.-)%s+(%[[%d%.]+m%])$")
						if Prefix and ThaiText[Prefix] then
							return ThaiText[Prefix] .. " " .. SuffixLocal
						end
						local Base = Clean:match("^(.-) Options$")
						if Base and ThaiText[Base] then
							return "ตั้งค่า " .. ThaiText[Base]
						end
						return Simple
					end
					return Simple
				end

