						AnchorPoint = Vector2.new(0.5, 0.5),
						BackgroundColor3 = Theme.Window,
						BackgroundTransparency = Theme.WindowAlpha,
						BorderSizePixel = 0,
						ClipsDescendants = false,
						Parent = GuiLocal,
						ThemeTag = { BackgroundColor3 = "Window" },
					})
					Corner(MainLocal, 10)
					DynamicGradient(MainLocal, 90, function()
						return NeutralGradient(1.00, 0.82)
					end)

					local BackgroundLocal = MainLocal

					local ShellDragHandle = New("TextButton", {
						Name = "ShellDragHandle",
						Size = UDim2.new(1, -24, 0, 22),
						Position = UDim2.fromOffset(12, 0),
						BackgroundTransparency = 1,
						AutoButtonColor = false,
						Text = "",
						ZIndex = 90,
						Parent = MainLocal,
					})

					local AccentClip = New("Frame", {
						Name = "AccentLine",
						Size = UDim2.fromOffset(0, 0),
						Position = UDim2.fromOffset(0, 0),
						BackgroundTransparency = 1,
						ClipsDescendants = true,
						BorderSizePixel = 0,
						Visible = false,
						ZIndex = 61,
						Parent = MainLocal,
					})
					local AccentStrip = New("Frame", {
						Size = UDim2.fromScale(2, 1),
						BackgroundColor3 = Color3.new(1, 1, 1),
						BorderSizePixel = 0,
						ZIndex = 61,
						Parent = AccentClip,
					})
					DynamicGradient(AccentStrip, 0, function()
						local ValueLocal, ValueLocal1, ValueLocal2 = Theme.Accent, Theme.AccentSoft, Theme.AccentDim
						local ValueLocal3 = Theme.TextMarked
						return ColorSequence.new({
							ColorSequenceKeypoint.new(0.00, ValueLocal2),
							ColorSequenceKeypoint.new(0.12, ValueLocal),
							ColorSequenceKeypoint.new(0.25, ValueLocal1),
							ColorSequenceKeypoint.new(0.37, ValueLocal3:Lerp(ValueLocal, 0.55)),
							ColorSequenceKeypoint.new(0.50, ValueLocal2),
							ColorSequenceKeypoint.new(0.62, ValueLocal),
							ColorSequenceKeypoint.new(0.75, ValueLocal1),
							ColorSequenceKeypoint.new(0.87, ValueLocal3:Lerp(ValueLocal, 0.55)),
							ColorSequenceKeypoint.new(1.00, ValueLocal2),
						})
					end)

					local AccentGlow = New("Frame", {
						Name = "AccentGlow",
						Size = UDim2.fromOffset(0, 0),
						Position = UDim2.fromOffset(0, Opts.AccentLineHeight or 2),
						BackgroundColor3 = Theme.Accent,
						BorderSizePixel = 0,
						ZIndex = 61,
						Parent = MainLocal,
						ThemeTag = { BackgroundColor3 = "Accent" },
					})
					New("UIGradient", {
						Rotation = 90,
						Transparency = NumberSequence.new(0.55, 1),
						Parent = AccentGlow,
					})
					AccentClip.Visible = Opts.AccentLine == true
					AccentGlow.Visible = Opts.AccentLine == true
					if Opts.AccentLine == true and Opts.AccentLineMotion == true then
						task.spawn(function()
							local Period = tonumber(Opts.AccentLineSpeed) or 4
							while AccentStrip.Parent do
								if
									Library.ReducedMotion
									or Library.PerformanceMode
									or not MainLocal.Visible
									or not GuiLocal.Enabled
									or (MainLocal:GetAttribute("Busy") or MainLocal:GetAttribute("Dragging"))
								then
									task.wait(0.25)
								else
									AccentStrip.Position = UDim2.fromScale(0, 0)
									local ValueLocal = TweenService:Create(
										AccentStrip,
										TweenInfo.new(Period, Enum.EasingStyle.Linear),
										{ Position = UDim2.fromScale(-1, 0) }
									)
									ValueLocal:Play()
									ValueLocal.Completed:Wait()
								end
							end
						end)
					end
					local InitialBackground =
						string.lower(tostring(Opts.BackgroundMode or (Opts.BackgroundImage and "image" or "clean")))
					if InitialBackground == "stripes" then
						InitialBackground = "striped"
					end
					if InitialBackground ~= "clean" and InitialBackground ~= "image" then
						InitialBackground = "striped"
					end
					local StripePattern = New("Frame", {
						Name = "StripedBackdrop",
						Size = UDim2.fromScale(1, 1),
						BackgroundTransparency = 1,
						ClipsDescendants = true,
						BorderSizePixel = 0,
						ZIndex = 1,
						Visible = InitialBackground == "striped",
						Parent = MainLocal,
					})
					Corner(StripePattern, 10)

					local STRIPES = {
						pepsi = { Gap = 26, Width = 13, Rot = 45, Cycle = 2, Weight = 0.6 },
						pinstripe = { Gap = 14, Width = 2, Rot = 45, Cycle = 3, Weight = 1 },
						candy = { Gap = 24, Width = 12, Rot = 45, Cycle = 1, Weight = 0.55 },
						dual = { Gap = 18, Width = 5, Rot = 45, Cycle = 2, Weight = 0.8 },
						crosshatch = { Gap = 18, Width = 1, Rot = 45, Cycle = 1, Weight = 1.0, Cross = true },
						chevron = { Gap = 22, Width = 8, Rot = 45, Cycle = 1, Weight = 0.65, Chevron = true },
						vertical = { Gap = 18, Width = 3, Rot = 0, Cycle = 2, Weight = 0.8 },
						scanlines = { Gap = 6, Width = 1, Rot = 90, Cycle = 1, Weight = 0.9, Scan = true },
						snake = {
							Kind = "snake",
							Gap = 34,
							Width = 2,
							Wave = 120,
							Amp = 8,
							Seg = 24,
							Cycle = 1,
							Weight = 1.2,
							Speed = 4,
						},
						dots = { Kind = "dots", Gap = 26, Width = 4, Cycle = 1, Weight = 1.5, Speed = 3 },
						checker = { Kind = "checker", Gap = 40, Cycle = 1, Weight = 0.35, Speed = 5 },
						rain = { Kind = "rain", Gap = 14, Width = 2, Cycle = 1, Weight = 1.4, Speed = 6 },
					}
					Library.StripeStyles = STRIPES
					StripePattern:SetAttribute("Opacity", math.clamp(tonumber(Opts.StripeOpacity) or 0.45, 0, 1))
					local StripeHolders = {}
					local StripeMotionLocal = { X = 0, Y = 0, Speed = 3, Version = 0 }

					local function StripeAlpha(WeightLocal)
						local OpacityLocal = StripePattern:GetAttribute("Opacity") or 0.3
						return 1 - math.clamp(OpacityLocal * 0.55 * WeightLocal, 0, 1)
					end

					local StripeYield = nil
					local function MakeStripe(ParentLocal, KeyLocal, WeightLocal, Props)
						if StripeYield then
							StripeYield()
						end
						local OriginalLocal = KeyLocal
						if StripePattern:GetAttribute("Grey") and Library.BackdropGrey[KeyLocal] then
							KeyLocal = Library.BackdropGrey[KeyLocal]
						end
						Props.BackgroundColor3 = Theme[KeyLocal]
						Props.BackgroundTransparency = StripeAlpha(WeightLocal)
						Props.BorderSizePixel = 0
						Props.ZIndex = 1
						Props.Parent = ParentLocal
						Props.ThemeTag = { BackgroundColor3 = KeyLocal }
						local Stripe = New("Frame", Props)
						Stripe:SetAttribute("VantaStripe", WeightLocal)
						Stripe:SetAttribute("VantaKey", OriginalLocal)
						return Stripe
					end

					local function FillDiagonal(ParentLocal, Spec, RotLocal, ColorAt)
						local Reach = WidthLocal + HeightLocal
						local Span = Reach * 2 + Spec.Gap * 8
						local BaseX = -Reach - Spec.Gap * 4
						local Holder = New("Frame", {
							Name = "StripeHolder",
							Size = UDim2.new(0, Span, 1, 0),
							Position = UDim2.fromOffset(BaseX, 0),
							BackgroundTransparency = 1,
							BorderSizePixel = 0,
							ZIndex = 1,
							Parent = ParentLocal,
						})
						Holder:SetAttribute("BaseX", BaseX)
						Holder:SetAttribute("BaseY", 0)
						local LengthLocal = Reach * 2.4
						for IndexLocal = 0, math.ceil(Span / Spec.Gap) do
							local KeyLocal, WeightLocal = ColorAt(IndexLocal)
							MakeStripe(Holder, KeyLocal, WeightLocal, {
								Size = UDim2.new(0, Spec.Width, 0, LengthLocal),
								AnchorPoint = Vector2.new(0.5, 0.5),
								Position = UDim2.new(0, IndexLocal * Spec.Gap, 0.5, 0),
								Rotation = RotLocal,
							})
						end
						table.insert(StripeHolders, Holder)
					end

					local function NewHolder(Argument, Argument1, BaseX, BaseY)
						local Holder = New("Frame", {
							Name = "StripeHolder",
							Size = UDim2.fromOffset(Argument, Argument1),
							Position = UDim2.fromOffset(BaseX, BaseY),
							BackgroundTransparency = 1,
							BorderSizePixel = 0,
							ZIndex = 1,
							Parent = StripePattern,
						})
						Holder:SetAttribute("BaseX", BaseX)
						Holder:SetAttribute("BaseY", BaseY)
						table.insert(StripeHolders, Holder)
						return Holder
					end

					local function BuildSpecial(Spec, ColorAt)
						local ValueLocal, ValueLocal1 = math.ceil(WidthLocal * 1.15), math.ceil(HeightLocal * 1.15)
						if Spec.Kind == "snake" then
							local Lambda, AmpLocal, SegLocal, GapLocal = Spec.Wave, Spec.Amp, Spec.Seg, Spec.Gap
							local Holder =
								NewHolder(ValueLocal + Lambda * 2, ValueLocal1 + GapLocal * 2, -Lambda, -GapLocal)
							local RowLocal = 0
							for IndexLocal = 0, ValueLocal1 + GapLocal * 2, GapLocal do
								local KeyLocal, WeightLocal = ColorAt(RowLocal)
								local PhaseLocal = (RowLocal % 2) * math.pi
								local Number, ValueLocal2 = 0, IndexLocal + AmpLocal * math.sin(PhaseLocal)
								for IndexLocal1 = SegLocal, ValueLocal + Lambda * 2, SegLocal do
									local ValueLocal3 = IndexLocal
										+ AmpLocal * math.sin(2 * math.pi * IndexLocal1 / Lambda + PhaseLocal)
									local ValueLocal4, ValueLocal5 = IndexLocal1 - Number, ValueLocal3 - ValueLocal2
									MakeStripe(Holder, KeyLocal, WeightLocal, {
										Size = UDim2.fromOffset(
											math.sqrt(ValueLocal4 * ValueLocal4 + ValueLocal5 * ValueLocal5) + 1,
											Spec.Width
										),
										AnchorPoint = Vector2.new(0.5, 0.5),
										Position = UDim2.fromOffset(
											(Number + IndexLocal1) / 2,
											(ValueLocal2 + ValueLocal3) / 2
										),
										Rotation = math.deg(math.atan2(ValueLocal5, ValueLocal4)),
									})
									Number, ValueLocal2 = IndexLocal1, ValueLocal3
								end
								RowLocal = RowLocal + 1
							end
							StripeMotionLocal.X, StripeMotionLocal.Y = Lambda, 0
						elseif Spec.Kind == "dots" then
							local ValueLocal2, ValueLocal3 = Spec.Gap, Spec.Width
							local Holder = NewHolder(
								ValueLocal + ValueLocal2 * 4,
								ValueLocal1 + ValueLocal2 * 4,
								-ValueLocal2 * 2,
								-ValueLocal2 * 2
							)
							for IndexLocal = 0, math.ceil((ValueLocal1 + ValueLocal2 * 4) / ValueLocal2) do
								for IndexLocal1 = 0, math.ceil((ValueLocal + ValueLocal2 * 4) / ValueLocal2) do
									local DotLocal = MakeStripe(Holder, "AccentSoft", Spec.Weight, {
										Size = UDim2.fromOffset(ValueLocal3, ValueLocal3),
										AnchorPoint = Vector2.new(0.5, 0.5),
										Position = UDim2.fromOffset(
											IndexLocal1 * ValueLocal2 + (IndexLocal % 2) * ValueLocal2 / 2,
											IndexLocal * ValueLocal2
										),
									})
									Corner(DotLocal, ValueLocal3, true)
								end
							end
							StripeMotionLocal.X, StripeMotionLocal.Y = ValueLocal2, ValueLocal2 * 2
						elseif Spec.Kind == "checker" then
							local ValueLocal2 = Spec.Gap
							local Holder = NewHolder(
								ValueLocal + ValueLocal2 * 4,
								ValueLocal1 + ValueLocal2 * 4,
								-ValueLocal2 * 2,
								-ValueLocal2 * 2
							)
							for IndexLocal = 0, math.ceil((ValueLocal1 + ValueLocal2 * 4) / ValueLocal2) do
								for IndexLocal1 = 0, math.ceil((ValueLocal + ValueLocal2 * 4) / ValueLocal2) do
									if (IndexLocal1 + IndexLocal) % 2 == 0 then
										MakeStripe(Holder, "AccentSoft", Spec.Weight, {
											Size = UDim2.fromOffset(ValueLocal2, ValueLocal2),
											Position = UDim2.fromOffset(
												IndexLocal1 * ValueLocal2,
												IndexLocal * ValueLocal2
											),
										})
									end
								end
							end
							StripeMotionLocal.X, StripeMotionLocal.Y = ValueLocal2, ValueLocal2
						elseif Spec.Kind == "rain" then
							local Rng = Random.new(1337)
							local Holder = NewHolder(ValueLocal, ValueLocal1 * 2, 0, -ValueLocal1)
							for IndexLocal = 0, ValueLocal, Spec.Gap do
								for _ = 1, 2 do
									local ValueLocal2 = Rng:NextInteger(0, ValueLocal1)
									local Len = Rng:NextInteger(24, 80)
									local KeyLocal = Rng:NextNumber() < 0.3 and "TextBright" or "AccentSoft"
									for Copy = 0, 1 do
										local Streak = MakeStripe(Holder, KeyLocal, Spec.Weight, {
											Size = UDim2.fromOffset(Spec.Width, Len),
											Position = UDim2.fromOffset(IndexLocal, ValueLocal2 + Copy * ValueLocal1),
										})
										New("UIGradient", {
											Rotation = 90,
											Transparency = NumberSequence.new(1, 0),
											Parent = Streak,
										})
									end
								end
							end
							StripeMotionLocal.X, StripeMotionLocal.Y = 0, ValueLocal1
						end
					end

					local function BuildStripes(Variant)
						Variant = string.lower(tostring(Variant or "pepsi"))
						if not STRIPES[Variant] then
							Variant = "pepsi"
						end
						local Spec = STRIPES[Variant]
						for _, Child in ipairs(StripePattern:GetChildren()) do
							if not Child:IsA("UICorner") then
								for _, Object in ipairs(Child:GetDescendants()) do
									Library:Untag(Object)
								end
								Library:Untag(Child)
								Child:Destroy()
							end
						end
						table.clear(StripeHolders)

						local function ColorAt(Argument)
							local Even = Argument % 2 == 0
							if Variant == "pepsi" then
								return Even and "Accent" or "TextBright", Even and Spec.Weight or Spec.Weight * 0.3
							elseif Variant == "dual" then
								return Even and "Accent" or "TextMarked", Spec.Weight
							elseif Variant == "vertical" then
								return Even and "AccentSoft" or "TextBright", Even and Spec.Weight or Spec.Weight * 0.5
							elseif Variant == "snake" then
								return Even and "AccentSoft" or "TextMarked", Even and Spec.Weight or Spec.Weight * 0.6
							elseif Variant == "pinstripe" then
								if Argument % 3 == 0 then
									return "AccentSoft", Spec.Weight
								end
								return "TextBright", Spec.Weight * 0.8
							end
							return "AccentSoft", Spec.Weight
						end

						if Spec.Kind then
							BuildSpecial(Spec, ColorAt)
						elseif Spec.Scan then
							local Total = HeightLocal * 2 + Spec.Gap * 4
							local BaseY = -Spec.Gap * 2
							local Holder = New("Frame", {
								Name = "StripeHolder",
								Size = UDim2.new(1, 0, 0, Total),
								Position = UDim2.fromOffset(0, BaseY),
								BackgroundTransparency = 1,
								BorderSizePixel = 0,
								ZIndex = 1,
								Parent = StripePattern,
							})
							Holder:SetAttribute("BaseX", 0)
							Holder:SetAttribute("BaseY", BaseY)
							for IndexLocal = 0, math.ceil(Total / Spec.Gap) do
								local KeyLocal, WeightLocal = ColorAt(IndexLocal)
								MakeStripe(Holder, KeyLocal, WeightLocal, {
									Size = UDim2.new(1, 0, 0, Spec.Width),
									Position = UDim2.fromOffset(0, IndexLocal * Spec.Gap),
								})
							end
							table.insert(StripeHolders, Holder)
							StripeMotionLocal.X, StripeMotionLocal.Y = 0, Spec.Gap * Spec.Cycle
						elseif Spec.Chevron then
							for Half = 0, 1 do
								local Clip = New("Frame", {
									Name = "ChevronHalf",
									Size = UDim2.fromScale(1, 0.5),
									Position = UDim2.fromScale(0, Half * 0.5),
									BackgroundTransparency = 1,
									ClipsDescendants = true,
									BorderSizePixel = 0,
									ZIndex = 1,
									Parent = StripePattern,
								})
								FillDiagonal(Clip, Spec, Half == 0 and Spec.Rot or -Spec.Rot, ColorAt)
							end
							StripeMotionLocal.X, StripeMotionLocal.Y = Spec.Gap * Spec.Cycle, 0
						else
							FillDiagonal(StripePattern, Spec, Spec.Rot, ColorAt)
							if Spec.Cross then
								FillDiagonal(StripePattern, Spec, -Spec.Rot, ColorAt)
							end
							StripeMotionLocal.X, StripeMotionLocal.Y = Spec.Gap * Spec.Cycle, 0
						end
						StripeMotionLocal.Speed = (Spec.Speed or 1.5 * Spec.Cycle)
							* ((tonumber(Opts.StripeSpeed) or 2.5) / 2.5)
						StripeMotionLocal.Version = StripeMotionLocal.Version + 1
						StripePattern:SetAttribute("Variant", Variant)
						return Variant
					end
					BuildStripes(Opts.StripeStyle or "pepsi")

					if Opts.StripeMotion ~= false then
						task.spawn(function()
							local function CanMove()
								return not Library.ReducedMotion
									and not Library.PerformanceMode
									and not Library.Unfocused
									and StripePattern.Visible
									and MainLocal.Visible
									and GuiLocal.Enabled
									and not (MainLocal:GetAttribute("Busy") or MainLocal:GetAttribute("Dragging"))
									and not StripePattern:GetAttribute("Paused")
							end
							while StripePattern.Parent do
								if not CanMove() then
									task.wait(0.1)
								else
									local VersionLocal = StripeMotionLocal.Version
									local Tweens, Longest = {}, 0
									local Total =
										math.max(math.abs(StripeMotionLocal.X), math.abs(StripeMotionLocal.Y), 1)
									for _, Holder in ipairs(StripeHolders) do
										if Holder.Parent then
											local ValueLocal, ValueLocal1 =
												Holder:GetAttribute("BaseX") or 0, Holder:GetAttribute("BaseY") or 0
											local ValueLocal2, ValueLocal3 =
												ValueLocal + StripeMotionLocal.X, ValueLocal1 + StripeMotionLocal.Y

											local Cur = Holder.Position
											local LeftLocal = math.max(
												math.abs(ValueLocal2 - Cur.X.Offset),
												math.abs(ValueLocal3 - Cur.Y.Offset)
											)
											if LeftLocal < 0.5 or LeftLocal > Total + 1 then
												Holder.Position = UDim2.fromOffset(ValueLocal, ValueLocal1)
												LeftLocal = Total
											end
											local DurationLocal = StripeMotionLocal.Speed * LeftLocal / Total
											Longest = math.max(Longest, DurationLocal)
											table.insert(
												Tweens,
												TweenService:Create(
													Holder,
													TweenInfo.new(DurationLocal, Enum.EasingStyle.Linear),
													{ Position = UDim2.fromOffset(ValueLocal2, ValueLocal3) }
												)
											)
										end
									end
									if #Tweens == 0 then
										task.wait(0.25)
									else
										for _, ValueLocal in ipairs(Tweens) do
											ValueLocal:Play()
										end
										local StartedLocal = os.clock()
										while
											os.clock() - StartedLocal < Longest
											and StripeMotionLocal.Version == VersionLocal
											and CanMove()
										do
											task.wait(0.05)
										end
										for _, ValueLocal in ipairs(Tweens) do
											ValueLocal:Cancel()
										end
										if StripeMotionLocal.Version ~= VersionLocal then
											for _, Holder in ipairs(StripeHolders) do
												if Holder.Parent then
													Holder.Position = UDim2.fromOffset(
														Holder:GetAttribute("BaseX") or 0,
														Holder:GetAttribute("BaseY") or 0
													)
												end
											end
										end
									end
								end
							end
						end)
					end
					local StripeTexture = New("ImageLabel", {
						Name = "BackdropTexture",
						Size = UDim2.fromScale(1, 1),
						BackgroundTransparency = 1,
						Image = Opts.BackgroundImage or "",
						ImageColor3 = Theme.AccentSoft,
						ImageTransparency = Opts.BackgroundTransparency or 0.94,
						ScaleType = Enum.ScaleType.Crop,
						BorderSizePixel = 0,
						ZIndex = 1,
						Visible = InitialBackground == "image" and Opts.BackgroundImage ~= nil,
						Parent = MainLocal,
						ThemeTag = { ImageColor3 = "AccentSoft" },
					})
					Corner(StripeTexture, 10)
					local ShadowLocal = New("ImageLabel", {
						Name = "AmbientShadow",
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.new(0.5, 0, 0.5, -2),
						Size = UDim2.new(1, 30, 1, 30),
						BackgroundTransparency = 1,
						Image = "rbxassetid://5587865193",
						ImageColor3 = Color3.fromRGB(0, 0, 0),
						ImageTransparency = 1,
						Visible = false,
						ScaleType = Enum.ScaleType.Slice,
						SliceCenter = Rect.new(49, 49, 450, 450),
						ZIndex = 0,
						Parent = MainLocal,
					})
					local AuraLocal = New("ImageLabel", {
						Name = "AccentAura",
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromScale(0.5, 0.5),
						Size = UDim2.new(1, 18, 1, 18),
						BackgroundTransparency = 1,
						Image = "rbxassetid://5587865193",
						ImageColor3 = Theme.AccentDim,
						ImageTransparency = 1,
						Visible = false,
						ScaleType = Enum.ScaleType.Slice,
						SliceCenter = Rect.new(49, 49, 450, 450),
						ZIndex = 0,
						Parent = MainLocal,
						ThemeTag = { ImageColor3 = "AccentDim" },
					})
					local ScaleLocal = New("UIScale", { Parent = MainLocal })

					local TitleCapsuleLocal = New("Frame", {
						Name = "IdentityCapsule",
						Size = UDim2.new(0, 0, 0, 36),
						AutomaticSize = Enum.AutomaticSize.X,
						BackgroundColor3 = Theme.TopBar,
						BorderSizePixel = 0,
						ZIndex = 200,
						Parent = GuiLocal,
						ThemeTag = { BackgroundColor3 = "TopBar" },
					})
					Corner(TitleCapsuleLocal, 11, true)
					DynamicGradient(TitleCapsuleLocal, 90, function()
						return NeutralGradient(1.00, 0.97)
					end)
					local CapsuleStroke = Stroke(TitleCapsuleLocal, Theme.WindowBorder, 1, 0.15)
					Pad(TitleCapsuleLocal, 0, 12, 0, 12)
					local CapsuleScale = New("UIScale", { Scale = 1, Parent = TitleCapsuleLocal })
					local CapsuleHit = New("TextButton", {
						Size = UDim2.fromScale(1, 1),
						BackgroundTransparency = 1,
						Text = "",
						AutoButtonColor = false,
						ZIndex = 202,
						Parent = TitleCapsuleLocal,
					})
					local CapsuleRow = New("Frame", {
						Size = UDim2.new(0, 0, 1, 0),
						AutomaticSize = Enum.AutomaticSize.X,
						BackgroundTransparency = 1,
						ZIndex = 201,
						Parent = TitleCapsuleLocal,
					})
					local CapsuleList = List(CapsuleRow, 4, Enum.FillDirection.Horizontal)
					CapsuleList.VerticalAlignment = Enum.VerticalAlignment.Center
					local CapsuleBrand = New("ImageLabel", {
						Name = "A0LogoImage",
						Image = "rbxassetid://118677754990717",
						ImageColor3 = Color3.new(1, 1, 1),
						ResampleMode = Enum.ResamplerMode.Default,
						ScaleType = Enum.ScaleType.Fit,
						BackgroundTransparency = 1,
						Size = UDim2.fromOffset(32, 32),
						LayoutOrder = 0,
						ZIndex = 201,
						Parent = CapsuleRow,
					})
					local CapsuleTab = Label(CapsuleRow, "| Home", Theme.AccentSoft, 13, Theme.FontMedium)
					CapsuleTab.Size = UDim2.new(0, 0, 1, 0)
