							end
							local Count, ContentWidth = 0, 0
							for _, Child in ipairs(TabBarLocal:GetChildren()) do
								if Child:IsA("GuiObject") and Child.Visible then
									Count += 1
									ContentWidth += Child.AbsoluteSize.X
								end
							end
							local ValueLocal = math.max(ScaleLocal.Scale, 0.0001)
							local Spacing = PreferredSpacing
							if Count > 1 then
								local FitSpacing = (AvailableLocal - ContentWidth) / ((Count - 1) * ValueLocal)
								Spacing =
									math.max(math.min(6, PreferredSpacing), math.min(PreferredSpacing, FitSpacing))
							end
							if TabList.Padding.Offset ~= Spacing then
								TabList.Padding = UDim.new(0, Spacing)
							end
							local Overflow = ContentWidth + math.max(0, Count - 1) * Spacing * ValueLocal
								> AvailableLocal + 0.5
							TabList.HorizontalAlignment = Overflow and Enum.HorizontalAlignment.Left
								or PreferredAlignment
							if not Overflow and TabBarLocal.CanvasPosition.X ~= 0 then
