					local function FocusSearchResult(ItemLocal)
						local TargetLocal = ItemLocal and ItemLocal.Entry and ItemLocal.Entry.Instance
						if not TargetLocal or not TargetLocal.Parent then
							return
						end

						local PathLocal, Seen, Groups = {}, {}, {}
						local OwnerTarget, Node = TargetLocal, TargetLocal
						while Node and not Seen[Node] do
							Seen[Node] = true
							local GroupLocal = WindowLocal.SectionsByFrame and WindowLocal.SectionsByFrame[Node]
							if GroupLocal and GroupLocal.SetOpen then
								table.insert(Groups, GroupLocal)
							end
							local RecordLocal = WindowLocal.FloatingOwners and WindowLocal.FloatingOwners[Node]
							if RecordLocal then
								table.insert(PathLocal, 1, RecordLocal)
								OwnerTarget = RecordLocal.OwnerInstance
								Node = OwnerTarget
							else
								Node = Node.Parent
							end
						end
						local SelectedTab
						for _, Candidate in ipairs(WindowLocal.Tabs) do
							if OwnerTarget:IsDescendantOf(Candidate.Page) then
								SelectedTab = Candidate
								break
							end
						end
						if not SelectedTab then
							return
						end
						for _, GroupLocal in ipairs(Groups) do
							GroupLocal:SetOpen(true)
						end
						Node = OwnerTarget
						while Node and Node ~= SelectedTab.Page do
							local SectionLocal = WindowLocal.SectionsByFrame and WindowLocal.SectionsByFrame[Node]
							if SectionLocal and SectionLocal.SetOpen then
								SectionLocal:SetOpen(true)
							end
							Node = Node.Parent
						end
						WindowLocal:SetTab(SelectedTab)
						WindowLocal:CloseFloating()
						task.defer(function()
							if not TargetLocal.Parent or not SelectedTab.Page.Parent then
								return
							end
							RunService.Heartbeat:Wait()
							if not TargetLocal.Parent then
								return
							end
							local ScaleLocal1 = math.max(WindowLocal.Scale.Scale, 0.05)
							local function RevealIn(ScrollLocal, Control)
								local OffsetLocal = ScrollLocal.CanvasPosition.Y
									+ (Control.AbsolutePosition.Y - ScrollLocal.AbsolutePosition.Y) / ScaleLocal1
									- 16
								local Maximum =
									math.max(0, ScrollLocal.AbsoluteCanvasSize.Y - ScrollLocal.AbsoluteWindowSize.Y)
								ScrollLocal.CanvasPosition = Vector2.new(0, math.clamp(OffsetLocal, 0, Maximum))
							end
							RevealIn(SelectedTab.Page, OwnerTarget)
							RunService.Heartbeat:Wait()
							for IndexLocal, RecordLocal in ipairs(PathLocal) do
								if not RecordLocal.Anchor.Parent then
									return
								end
								WindowLocal:ToggleFloating(RecordLocal.Panel, RecordLocal.Anchor)
								RunService.Heartbeat:Wait()
								local NextTarget = PathLocal[IndexLocal + 1] and PathLocal[IndexLocal + 1].OwnerInstance
									or TargetLocal
								if RecordLocal.Scroll then
									RevealIn(RecordLocal.Scroll, NextTarget)
								end
							end
							local Outline = Stroke(TargetLocal, Theme.Accent, 1.4, 0)
							Tween(Outline, { Transparency = 1 }, TweenInfo.new(0.8))
							task.delay(0.85, function()
								if Outline.Parent then
									Outline:Destroy()
								end
							end)
						end)
					end

					local function RefreshSearchIndex()
						local VersionLocal = Library.RegistryVersion or 0
						if VersionLocal == IndexedVersion then
