								if
									type(EntryLocal) == "table"
									and EntryLocal.Instance
									and EntryLocal.Instance.Parent
								then
									local LabelLocal =
										tostring(EntryLocal.Label or HumanizeFlag(FlagLocal)):gsub("<[^>]+>", "")
									local KindLocal = tostring(EntryLocal.Type or "Control")
									table.insert(SearchIndex, {
										Entry = EntryLocal,
										Label = LabelLocal,
										Kind = KindLocal,
										Hay = string.lower(
											LabelLocal
												.. " "
												.. (ThaiText[LabelLocal] or LabelLocal)
												.. " "
												.. tostring(FlagLocal)
