					local function RebuildResults(Force)
						if not Force and not CommandPanel.Frame.Visible then
							return
						end
						RefreshSearchIndex()
						local Query = string.lower(CommandBox.Text or ""):match("^%s*(.-)%s*$")
						local ShownLocal = 0
						for _, ItemLocal in ipairs(SearchIndex) do
