								local RowLocal = GetSearchRow(ShownLocal)
								RowLocal.Item = ItemLocal
								RowLocal.Title.Text = ItemLocal.Label
								RowLocal.Kind.Text = ItemLocal.Kind
								RowLocal.Button.Visible = true
								if ShownLocal == SEARCH_LIMIT then
