					local function GetWindowCenter()
						local ValueLocal = GuiLocal.AbsoluteSize
						local Pos = MainLocal.Position
						return Vector2.new(
							ValueLocal.X * Pos.X.Scale + Pos.X.Offset,
							ValueLocal.Y * Pos.Y.Scale + Pos.Y.Offset
						)
					end

					local function GetVisualHalf()
						local ValueLocal = math.max(ScaleLocal.Scale, 0.05)
						return Vector2.new(WindowLocal.Width * ValueLocal * 0.5, WindowLocal.Height * ValueLocal * 0.5)
					end

					local function ClampWindowCenter(CenterLocal, BottomRoom, TopRoom)
						local ValueLocal = GuiLocal.AbsoluteSize
						local Half = GetVisualHalf()
						local MinX = Half.X + 10
						local MaxX = math.max(MinX, ValueLocal.X - Half.X - 10)
						local MinY = Half.Y + (TopRoom or 10)
						local MaxY = math.max(MinY, ValueLocal.Y - Half.Y - (BottomRoom or 42))
						return Vector2.new(math.clamp(CenterLocal.X, MinX, MaxX), math.clamp(CenterLocal.Y, MinY, MaxY))
					end

					local function FitLocal()
						local ValueLocal = GuiLocal.AbsoluteSize
						if ValueLocal.X <= 0 then
							return
						end
						if WindowLocal.DeviceSizing then
							local AdaptiveTouch = UserInputService.TouchEnabled or ValueLocal.X <= 700
							local NextSizing = Library:_ResolveWindowSize(Opts, ValueLocal, AdaptiveTouch)
							local ProfileChanged = NextSizing.Key ~= WindowLocal.SizeProfileKey
							local WidthChanged = math.abs(
								NextSizing.Width - (WindowLocal.ProfileWidth or NextSizing.Width)
							) > 1
							local HeightCapChanged = math.abs(
								NextSizing.Height - (WindowLocal.ProfileHeight or NextSizing.Height)
							) > 1
							if ProfileChanged or WidthChanged or HeightCapChanged then
								WindowLocal.SizeProfileKey = NextSizing.Key
								WindowLocal.ProfileWidth, WindowLocal.ProfileHeight =
									NextSizing.Width, NextSizing.Height
								WindowLocal.DeviceProfile, WindowLocal.SizeOrientation =
									NextSizing.Device, NextSizing.Orientation
								WindowLocal.CompactMobile = NextSizing.Device == "mobile"
								WindowLocal.MinWidth, WindowLocal.MinHeight = NextSizing.MinWidth, NextSizing.MinHeight
								if WindowLocal.ResizeGrip then
									WindowLocal.ResizeGrip.Visible = Opts.Resizable ~= false
										and not WindowLocal.CompactMobile
								end
								WindowLocal.StackColumns = NextSizing.StackColumns
								WindowLocal.Width = NextSizing.Width
								if ProfileChanged then
									WindowLocal.Height = NextSizing.Height
								else
									WindowLocal.Height = math.min(WindowLocal.Height, NextSizing.Height)
								end
								MainLocal.Size = UDim2.fromOffset(WindowLocal.Width, WindowLocal.Height)
								WindowLocal:CloseFloating()
								WidthLocal, HeightLocal =
									math.max(WidthLocal, WindowLocal.Width), math.max(HeightLocal, WindowLocal.Height)
								task.defer(function()
									if MainLocal.Parent and WindowLocal.StripeBuilder then
										WindowLocal.StripeBuilder(WindowLocal.StripeVariant)
									end
								end)
							end
						end
						local TopRoom = WindowLocal.CompactMobile
								and (WindowLocal.SizeOrientation == "Portrait" and 78 or 38)
							or 50
						local BottomRoom = WindowLocal.TabStyle == "dock" and 88 or 40
						local ValueLocal1
						if WindowLocal.DeviceSizing then
							local AvailableLocal = math.min(
								math.max(1, ValueLocal.X - 16) / WindowLocal.Width,
								math.max(1, ValueLocal.Y - TopRoom - BottomRoom - 8) / WindowLocal.Height
							)
							ValueLocal1 = math.min(AvailableLocal, WindowLocal.UserScale or 1)
						else
							ValueLocal1 = math.clamp(
								math.min(
									(ValueLocal.X - 24) / WindowLocal.Width,
									(ValueLocal.Y - 82) / WindowLocal.Height
