					local function SyncOuterDragHandle()
						local CenterLocal = GetWindowCenter()
						local Half = GetVisualHalf()
						OuterDragHandleLocal.Position = UDim2.fromOffset(CenterLocal.X, CenterLocal.Y + Half.Y + 6)
						local ValueLocal = math.max(ScaleLocal.Scale, 0.05)
						local LeftLocal = CenterLocal.X - WindowLocal.Width * ValueLocal * 0.5
						local TopLocal = CenterLocal.Y - WindowLocal.Height * ValueLocal * 0.5
						if WindowLocal.TitleCapsuleScale then
							WindowLocal.TitleCapsuleScale.Scale = 1
						end
						local CapsuleGap = WindowLocal.CompactMobile and 34 or 40
						TitleCapsuleLocal.Position = UDim2.fromOffset(LeftLocal, TopLocal - CapsuleGap * ValueLocal)

						local SearchGap = WindowLocal.CompactMobile and 7 or 9
						local TitleWidth = math.max(TitleCapsuleLocal.AbsoluteSize.X, 90)
						CapsuleSearch.Position =
							UDim2.fromOffset(LeftLocal + TitleWidth + SearchGap, TopLocal - CapsuleGap * ValueLocal)
						if WindowLocal.LanguageSwitch then
							local ValueLocal1 = LeftLocal + WindowLocal.Width * ValueLocal - 92
							local ValueLocal2 = TopLocal - CapsuleGap * ValueLocal
							local Viewport = GuiLocal.AbsoluteSize
							WindowLocal.LanguageSwitch.Position = UDim2.fromOffset(
								math.floor(math.clamp(ValueLocal1, 8, math.max(8, Viewport.X - 100)) + 0.5),
								math.floor(math.max(8, ValueLocal2) + 0.5)
