						end
						if WindowLocal.TabStyle == "dock" and WindowLocal.TabBar then
							local TabCount = math.max(#WindowLocal.Tabs, 1)
							local NaturalDockWidth = TabCount * 52 + math.max(0, TabCount - 1) * 8 + 12
							local DockScaleLocal = math.min(ValueLocal, 1)
							local AvailableWidth = math.max(1, GuiLocal.AbsoluteSize.X - 16)
