					task.defer(SyncOuterDragHandle)

					local function BeginDrag(InputLocal, ToggleOnTap)
						if Opts.Draggable == false then
							return
						end
						if
							InputLocal.UserInputType ~= Enum.UserInputType.MouseButton1
							and InputLocal.UserInputType ~= Enum.UserInputType.Touch
						then
							return
						end
						if Dragging then
