						Dragging = true
						DragMoved = false
						DragToggleOnTap = ToggleOnTap == true
						ActiveInput = InputLocal
						DragStart = PointerPosition(InputLocal)
						DragCurrent = DragStart
						DragStartCenter = GetWindowCenter()
						MainLocal:SetAttribute("Dragging", true)
						WindowLocal:CloseFloating()
					end

					local function UpdateDrag(PositionLocal)
						if not Dragging or not DragStart or not DragStartCenter or not PositionLocal then
							return
						end
						DragCurrent = PositionLocal
						local Delta = DragCurrent - DragStart
						if not DragMoved and Delta.Magnitude >= DRAG_THRESHOLD then
							DragMoved = true
						end
						if not DragMoved then
							return
						end
						local TopRoom = WindowLocal.CompactMobile
								and (WindowLocal.SizeOrientation == "Portrait" and 78 or 38)
							or 50
						local BottomRoom = WindowLocal.TabStyle == "dock" and 88 or 40
						local CenterLocal =
							ClampWindowCenter(DragStartCenter + Vector2.new(Delta.X, Delta.Y), BottomRoom, TopRoom)
						MainLocal.Position = UDim2.fromOffset(CenterLocal.X, CenterLocal.Y)
						WindowLocal.RestPosition = MainLocal.Position
					end

					local function FinishDrag(InputLocal)
