						local ToggleLocal = DragToggleOnTap and not DragMoved
						Dragging = false
						DragMoved = false
						DragToggleOnTap = false
						ActiveInput = nil
						DragStart = nil
						DragCurrent = nil
						DragStartCenter = nil
						MainLocal:SetAttribute("Dragging", false)
						WindowLocal.RestPosition = MainLocal.Position
						if ToggleLocal then
							WindowLocal:SetVisible(not WindowLocal.Visible)
						end
					end

					local function BindDragSource(SourceLocal, ToggleOnTap)
						if not SourceLocal or typeof(SourceLocal) ~= "Instance" then
