					local SyncBuild = BuildStripes
					local ActiveBuild = nil
					local BuiltW, BuiltH = WidthLocal, HeightLocal
					local Made = 0
					StripeYield = function()
						if not ActiveBuild or coroutine.running() ~= ActiveBuild then
							return
						end
						Made = Made + 1
						if Made % 40 == 0 then
							task.wait()
							if coroutine.running() ~= ActiveBuild then
								error("vanta_cancel", 0)
							end
						end
					end
					WindowLocal.StripeBuilder = function(Variant)
						Variant = string.lower(tostring(Variant or "pepsi"))
						if not STRIPES[Variant] then
							Variant = "pepsi"
						end
						task.defer(function()
							ActiveBuild = coroutine.running()
							local ValueLocal = ActiveBuild
