local function A0LoadInterface(GameName, Dependencies)
	local Package = A0InterfaceFactory()
	assert(Package.Game == GameName and type(Package.Create) == "function", "A0 interface mismatch")
	local Interface = Package.Create(Dependencies)
	assert(type(Interface) == "table" and Interface.Library, "A0 interface failed")
	return Interface
end

