	SurvivorHealthy = Color3.fromRGB(75, 220, 120),
	SurvivorInjured = Color3.fromRGB(65, 200, 105),
	SurvivorKnocked = Color3.fromRGB(55, 180, 95),
	Generator = Color3.fromRGB(255, 235, 145),
	Pallet = Color3.fromRGB(255, 155, 55),
	Vault = Color3.fromRGB(255, 155, 55),
	Gate = Color3.fromRGB(255, 195, 125),
	Me = Color3.fromRGB(75, 220, 120),
}
local function A0IsWhiteESP(Value)
	return typeof(Value) == "Color3" and Value.R > 0.998 and Value.G > 0.998 and Value.B > 0.998
end
local function A0NormalizeESPColors(Settings, Startup)
	if type(Settings.ESPColors) ~= "table" then
		Settings.ESPColors = {}
	end
	local Migrate = Startup or (tonumber(Settings.ESPColorPaletteVersion) or 0) < 1
	for Key, Default in pairs(A0ESPPalette) do
		local Current = Settings.ESPColors[Key]
		if typeof(Current) ~= "Color3" or (Migrate and A0IsWhiteESP(Current)) then
			Settings.ESPColors[Key] = Default
		end
	end
	if Migrate then
		for _, Part in ipairs({ "Text", "Fill", "Outline" }) do
			local ModeKey = "ESP" .. Part .. "ColorMode"
			if Settings[ModeKey] == "Custom" and A0IsWhiteESP(Settings["ESP" .. Part .. "Color"]) then
				Settings[ModeKey] = "Role Color"
			end
		end
	end
	Settings.ESPColorPaletteVersion = 1
end

local __A0MovementFilter = {}
function __A0MovementFilter.Normalize(ValueLocal)
	local KeyLocal = tostring(ValueLocal or "Both"):lower():gsub("%s+", "")
	local Aliases = {
		both = "Both",
		bothteams = "Both",
		survivors = "Survivors",
		survivor = "Survivors",
		survivorsonly = "Survivors",
		killer = "Killer",
		killersonly = "Killer",
		killeronly = "Killer",
		["ทั้งสองทีม"] = "Both",
		["ผู้รอดชีวิตเท่านั้น"] = "Survivors",
		["นักฆ่าเท่านั้น"] = "Killer",
	}
	return Aliases[KeyLocal] or "Both"
end
function __A0MovementFilter.Allows(Filter, TeamLocal)
	Filter = __A0MovementFilter.Normalize(Filter)
	if Filter == "Both" then
		return true
	end
	if TeamLocal == nil then
		return false
	end
	local KeyLocal = tostring(TeamLocal):lower():gsub("%s+", "")
	if Filter == "Survivors" then
		return KeyLocal == "survivors" or KeyLocal == "survivor"
	end
	return KeyLocal == "killer" or KeyLocal == "killers"
end

local __A0Boot = (function()
