		if self.ProgressTween then
			self.ProgressTween:Cancel()
			self.ProgressTween = nil
		end
		for _, ConnectionLocal in ipairs(self.Connections) do
			ConnectionLocal:Disconnect()
		end
		table.clear(self.Connections)
		if self.Fade then
