	function Boot:AwaitRelease()
		if self.Cancelled or self.Failed then
			return false
		end
		if self.Accepted then
			return true
		end
		self.ReleaseTickets += 1
		local Ticket = self.ReleaseTickets
		repeat
			RunLocal.Heartbeat:Wait()
		until self.Accepted or self.Cancelled or self.Failed
		if self.Cancelled or self.Failed then
			return false
		end
		local Due = (self.ReleasedAt or os.clock()) + math.min(math.floor((Ticket - 1) / 8), 11) / 60
		while os.clock() < Due do
			RunLocal.Heartbeat:Wait()
			if self.Cancelled or self.Failed then
				return false
			end
		end
		return true
	end
	function Boot:Describe()
		local Labels = {}
		for _, Job in pairs(self.Jobs) do
			Labels[#Labels + 1] = string.format("%s (%.1fs)", Job.Label, os.clock() - Job.StartedAt)
		end
		table.sort(Labels)
		local Missing = {}
		for _, Key in ipairs(self.Required) do
			if not self.Completed[Key] then
				Missing[#Missing + 1] = Key
			end
		end
		return string.format(
			"Phase: %s | Pending: %d | Jobs: %s | Missing: %s",
			self.CurrentPhase,
			self.Pending,
			table.concat(Labels, "; "),
			table.concat(Missing, ", ")
