			if ItemLocal:IsA("GuiObject") then
				Goals.BackgroundTransparency = 1
			end
			if ItemLocal:IsA("ImageLabel") or ItemLocal:IsA("ImageButton") then
				Goals.ImageTransparency = 1
			end
			if ItemLocal:IsA("TextLabel") or ItemLocal:IsA("TextButton") then
				Goals.TextTransparency = 1
				Goals.TextStrokeTransparency = 1
