		function Api:Silent(KindLocal, Args)
			local NameLocal = KindLocal .. "SilentAim"
			if not self:Alive() or not self.HookReady then
				return self:Record(NameLocal, false, "This client has no installed aim network hook")
			end
			local SettingsLocal = Deps.settings()[NameLocal]
			if not SettingsLocal or not SettingsLocal.Enabled then
				return false
			end
			local CharacterLocal, CameraLocal = Deps.character(), Deps.camera()
			if not CharacterLocal or not CameraLocal then
				return self:Record(NameLocal, false, "Character or camera unavailable")
			end
			local RadiusLocal = math.clamp(tonumber(SettingsLocal.FOVRadius) or 240, 1, 2000)
			local Candidates = {}
			local AimSettings = Deps.settings().SpearAimbot or {}
			local TargetPartLocal = KindLocal == "Spear" and (AimSettings.TargetPart or "UpperTorso") or "Head"
			for _, PlayerLocal in ipairs(Deps.players()) do
				if PlayerLocal ~= Deps.player then
					local Model, TeamLocal = PlayerLocal.Character, PlayerLocal.Team and PlayerLocal.Team.Name
					local Allowed = KindLocal == "Spear"
							and type(TeamLocal) == "string"
							and TeamLocal:lower():find("survivor", 1, true) ~= nil
						or KindLocal ~= "Spear"
							and (SettingsLocal.Target == "Both Teams" or TeamLocal == (SettingsLocal.Target or "Killer"))
					local HumanoidLocal = Model and Model:FindFirstChildOfClass("Humanoid")
					local PartLocal = Model
						and (
							Model:FindFirstChild(TargetPartLocal)
							or Model:FindFirstChild("HumanoidRootPart")
							or Model.PrimaryPart
						)
					if
						Allowed
						and Model
						and Model:GetAttribute("Knocked") ~= true
						and Model:GetAttribute("HookProgressDepleting") ~= true
						and Model:GetAttribute("IsHooked") ~= true
						and Model:GetAttribute("IsCarried") ~= true
						and HumanoidLocal
						and HumanoidLocal.Health > 0
						and PartLocal
						and PartLocal:IsA("BasePart")
					then
						local Screen, VisibleLocal = CameraLocal:WorldToViewportPoint(PartLocal.Position)
						if VisibleLocal and Screen.Z > 0 then
							local ValueLocal36, ValueLocal37 =
								Screen.X - CameraLocal.ViewportSize.X / 2, Screen.Y - CameraLocal.ViewportSize.Y / 2
							local DistanceLocal = math.sqrt(ValueLocal36 * ValueLocal36 + ValueLocal37 * ValueLocal37)
							if DistanceLocal <= RadiusLocal then
								Candidates[#Candidates + 1] = {
									part = PartLocal,
									dist = DistanceLocal,
									health = HumanoidLocal.Health,
									maxHealth = HumanoidLocal.MaxHealth or 100,
								}
							end
						end
					end
				end
			end
			local TargetLocal = Deps.choose(Candidates, SettingsLocal.Priority or "Nearest", RadiusLocal)
			if not TargetLocal then
				return self:Record(NameLocal, false, "No live target inside the configured FOV")
			end
			local DirectionLocal
			local SpearParameters
			if KindLocal == "Spear" then
				local VeilLocal = A0Features.Veil
				if not VeilLocal then
					return self:Record(NameLocal, false, "Veil adapter unavailable")
				end
				local Reason
				SpearParameters, Reason = VeilLocal:Parameters(Args)
				if not SpearParameters then
					return self:Record(NameLocal, false, Reason .. "; original shot preserved")
				end
				DirectionLocal = VeilLocal:Solve(TargetLocal.part, SpearParameters.Origin, SpearParameters.Speed)
			else
				if Deps.typeof(Args[2]) ~= "Vector3" then
					return self:Record(NameLocal, false, "Unexpected revolver argument schema; original shot preserved")
				end
				local OriginLocal = Deps.revolverOrigin and Deps.revolverOrigin(Args[1])
				if not OriginLocal then
					return self:Record(NameLocal, false, "Twist of Fate muzzle unavailable; original shot preserved")
				end
				local VelocityLocal = TargetLocal.part.AssemblyLinearVelocity
				if A0Features.Motion then
					VelocityLocal = A0Features.Motion:Sample(TargetLocal.part.Parent, VelocityLocal, TargetLocal.part)
				end
				if SettingsLocal.Prediction then
					DirectionLocal = A0Features.SolveLinearIntercept(
						Deps.vector,
						OriginLocal,
						TargetLocal.part.Position,
						VelocityLocal,
						tonumber(SettingsLocal.ProjectileSpeed) or 500
					)
				else
					local OffsetLocal = TargetLocal.part.Position - OriginLocal
					if OffsetLocal.Magnitude > 0.001 then
						DirectionLocal = OffsetLocal.Unit
					end
				end
			end
			if
				Deps.typeof(DirectionLocal) ~= "Vector3"
				or DirectionLocal.Magnitude < 0.01
				or DirectionLocal.X ~= DirectionLocal.X
				or DirectionLocal.Y ~= DirectionLocal.Y
				or DirectionLocal.Z ~= DirectionLocal.Z
				or math.abs(DirectionLocal.X) == math.huge
				or math.abs(DirectionLocal.Y) == math.huge
				or math.abs(DirectionLocal.Z) == math.huge
			then
				return self:Record(NameLocal, false, "Invalid aim solution; original shot preserved")
			end
			if KindLocal == "Spear" then
				if not A0Features.Veil:Apply(Args, SpearParameters, DirectionLocal) then
					return false
				end
			else
				Args[2] = DirectionLocal
			end
			return self:Record(NameLocal, true, "Outgoing direction updated (hit outcome unverified)")
		end
		function Api:Reset()
			self.Jobs.Vaults, self.Jobs.Pallets = nil, nil
			local Repair = self.Jobs.Generator
			if Repair and Repair.Started then
				pcall(function()
					Repair.Remote:FireServer(Repair.Point, false)
				end)
				Repair.Started = false
			end
			self.Jobs.Generator = nil
			for KindLocal, HeldLocal in pairs(self.Held) do
				local RemoteLocal = self:Remote(
					KindLocal == "Vaults" and "Window" or "Pallet",
					KindLocal == "Vaults" and "VaultCompleteEvent" or "PalletSlideCompleteEvent"
				)
				local PreviousLocal = Deps.releasing(true)
				if RemoteLocal then
					for TargetLocal in pairs(HeldLocal) do
						if TargetLocal.Parent then
							pcall(function()
								if KindLocal == "Vaults" then
									RemoteLocal:FireServer(TargetLocal, true)
								else
									RemoteLocal:FireServer(TargetLocal)
								end
							end)
						end
					end
				end
				Deps.releasing(PreviousLocal)
				table.clear(HeldLocal)
			end
			if ParryTrack then
				pcall(function()
					ParryTrack:Stop(0)
					ParryTrack:Destroy()
				end)
			end
			ParryTrack, ParryCharacter = nil, nil
		end
		function Api:Destroy()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			self:Reset()
		end
		Api:Record("InstantBandage", false, "Unavailable: no verified instant-bandage protocol in the reviewed sources")
		return Api
	end

	function A0Features.CreateHealing(Deps)
		local Api = { Target = nil, Remote = nil, Manual = false, Destroyed = false, RetryAt = 0, Status = "Idle" }
		local function BlockedLocal(Model)
			for _, KeyLocal in ipairs({ "IsHooked", "IsCarried", "HookProgressDepleting" }) do
				if Model:GetAttribute(KeyLocal) == true then
					return true
				end
			end
			return false
		end
		function Api:Stop(Reason)
			local TargetLocal, RemoteLocal = self.Target, self.Remote
			self.Target, self.Remote, self.Manual = nil, nil, false
			if TargetLocal and RemoteLocal then
				local SuccessLocal = pcall(function()
					RemoteLocal:FireServer(TargetLocal, false)
				end)
				self.Status = SuccessLocal and (Reason or "Stopped") or "Stop request failed"
			elseif Reason then
				self.Status = Reason
			end
		end
		function Api:Valid(Model)
			if not Model or not Model.Parent or BlockedLocal(Model) then
				return nil
			end
			local HumanoidLocal = Model:FindFirstChildOfClass("Humanoid")
			local RootLocal = Model:FindFirstChild("HumanoidRootPart") or Model:FindFirstChild("Torso")
			if
				HumanoidLocal
				and RootLocal
				and HumanoidLocal.Health > 0
				and HumanoidLocal.Health < HumanoidLocal.MaxHealth
			then
				return RootLocal
			end
			return nil
		end
		function Api:Select()
			local PlayerLocal, SettingsLocal = Deps.player, Deps.settings()
			local CharacterLocal = PlayerLocal.Character
			if not CharacterLocal or BlockedLocal(CharacterLocal) then
				return nil
			end
			local TeamLocal = PlayerLocal.Team and PlayerLocal.Team.Name:lower() or ""
			if not TeamLocal:find("survivor", 1, true) then
				return nil
			end
			local RootLocal = CharacterLocal:FindFirstChild("HumanoidRootPart")
			if not RootLocal then
				return nil
			end
			local Own = self:Valid(CharacterLocal)
			if Own then
				return Own
			end
			if not SettingsLocal.HealTeammates then
				return nil
			end
			local TargetLocal, Closest = nil, math.clamp(tonumber(SettingsLocal.HealRange) or 12, 3, 35)
			for _, Other in ipairs(Deps.players()) do
				if Other ~= PlayerLocal and Other.Team == PlayerLocal.Team then
					local PartLocal = self:Valid(Other.Character)
					if PartLocal then
						local DistanceLocal = (PartLocal.Position - RootLocal.Position).Magnitude
						if DistanceLocal <= Closest then
							TargetLocal, Closest = PartLocal, DistanceLocal
						end
					end
				end
			end
			return TargetLocal
		end
		function Api:Start(TargetLocal, ManualLocal)
			if self.Destroyed or not Deps.alive() then
				return false
			end
			if self.Target == TargetLocal and self.Remote and self.Remote.Parent then
				return true
			end
			self:Stop()
			local RemoteLocal = Deps.remote()
			if not TargetLocal or not TargetLocal.Parent or not RemoteLocal then
				self.Status = "Healing target or remote unavailable"
				return false
			end
			if Deps.clock() < self.RetryAt then
				return false
			end
			local SuccessLocal = pcall(function()
				RemoteLocal:FireServer(TargetLocal, true)
			end)
			if SuccessLocal then
				self.Target, self.Remote, self.Manual = TargetLocal, RemoteLocal, ManualLocal == true
				self.Status = "Healing channel requested; waiting for replicated progress"
			else
				self.Status = "Healing start request failed"
				self.RetryAt = Deps.clock() + 2
			end
			return SuccessLocal
		end
		function Api:Step()
			if self.Destroyed or not Deps.alive() then
				self:Stop("Session stopped")
				return
			end
			if self.Manual and self.Target then
				local Selected = self:Valid(Deps.player.Character)
				if Selected == self.Target and self.Remote and self.Remote.Parent then
					return
				end
				self:Stop("Manual healing finished or character changed")
			end
			if not Deps.settings().InstantHeal then
				if self.Target then
					self:Stop("Auto heal disabled")
				end
				return
			end
			local TargetLocal = self:Select()
			if TargetLocal then
				self:Start(TargetLocal, false)
			elseif self.Target then
				self:Stop("No eligible injured target")
			end
		end
		function Api:ManualToggle()
			if self.Target then
				self:Stop("Healing stopped")
				return true
			end
			local TargetLocal = self:Valid(Deps.player.Character)
			return self:Start(TargetLocal, true)
		end
		function Api:Destroy()
			if self.Destroyed then
				return
			end
			self.Destroyed = true
			self:Stop("Session stopped")
		end
		return Api
	end

	A0Features.UpdateUtil = { IntactSeen = setmetatable({}, { __mode = "k" }) }
	function A0Features.UpdateUtil.Part(Object)
		if not Object or not Object.Parent then
			return nil
		end
		if Object:IsA("BasePart") then
			return Object
		end
		if Object:IsA("Model") and Object.PrimaryPart then
			return Object.PrimaryPart
		end
		return Object:FindFirstChildWhichIsA("BasePart", true)
	end
	function A0Features.UpdateUtil.Pallet(Object)
		if not Object or not Object.Parent then
			return nil
		end
		local Node = Object
		for _ = 1, 5 do
			if not Node or Node == workspace then
				break
			end
			if
				Node:IsA("Model")
				and (
					Node.Name == "Pallet"
					or Node.Name == "Palletwrong"
					or (Node.Parent and Node.Parent.Name == "Pallets")
					or Node:FindFirstChild("Intact")
					or Node:FindFirstChild("PrimaryPartPallet")
					or Node:FindFirstChild("PalletPointSlide")
				)
			then
				return Node
			end
			Node = Node.Parent
		end
	end
	function A0Features.UpdateUtil.PalletActive(Object)
		if
			not Object
			or not Object.Parent
			or Object:GetAttribute("Intact") == false
			or Object:GetAttribute("Broken") == true
		then
			return false
		end
		local Intact = Object:FindFirstChild("Intact")
		if Intact then
			A0Features.UpdateUtil.IntactSeen[Object] = true
		end
		if not Intact and A0Features.UpdateUtil.IntactSeen[Object] then
			return false
		end
		if Intact and Intact:IsA("BoolValue") then
			return Intact.Value
		end
		return Intact ~= nil
			or Object:FindFirstChild("PrimaryPartPallet", true) ~= nil
			or Object:FindFirstChild("PalletPointSlide", true) ~= nil
			or Object.Name == "Palletwrong"
	end
	function A0Features.UpdateUtil.Gate(Object)
		if not Object or not Object.Parent then
			return nil
		end
		if Object.Name == "ExitLever" then
			return Object
		end
		local KeyLocal = Object.Name:lower()
		if KeyLocal:find("spawn", 1, true) or KeyLocal:find("spot", 1, true) or KeyLocal:find("marker", 1, true) then
			return nil
		end
		if KeyLocal:find("gate", 1, true) then
			return Object:FindFirstChild("ExitLever", true) or Object
		end
	end
	function A0Features.UpdateUtil.NormalizeGates(Objects)
		local ListLocal, Seen = {}, {}
		for _, Object in ipairs(Objects) do
			local GateLocal = A0Features.UpdateUtil.Gate(Object)
			if GateLocal and not Seen[GateLocal] then
				Seen[GateLocal] = true
				ListLocal[#ListLocal + 1] = GateLocal
			end
		end
		return ListLocal
	end
	function A0Features.UpdateUtil.GatePart(Object)
		if not Object or not Object.Parent then
			return nil
		end
		local Lever = Object.Name == "ExitLever" and Object or Object:FindFirstChild("ExitLever", true)
		if Lever then
			local MainLocal = Lever:FindFirstChild("Main", true)
			if MainLocal and MainLocal:IsA("BasePart") then
				return MainLocal
			end
			return A0Features.UpdateUtil.Part(Lever)
		end
		return A0Features.UpdateUtil.Part(Object)
	end
	function A0Features.UpdateUtil.Pumpkin(Object)
		if not Object or not Object.Parent then
			return nil
		end
		local Node, Named = Object, nil
		for _ = 1, 6 do
			if not Node or Node == workspace or Node.Name == "Map" then
				break
			end
			if Node.Name == "Pumpkins" then
				break
			end
			if (Node:IsA("Model") or Node:IsA("BasePart")) and Node.Name:lower():find("pumpkin", 1, true) then
				Named = Node
			end
			if Node.Parent and Node.Parent.Name == "Pumpkins" then
				if Node:IsA("Model") or Node:IsA("BasePart") then
					return Node
				end
				break
			end

			if
				(Node:IsA("Model") or Node:IsA("BasePart"))
				and Node.Parent
				and Node.Parent:IsA("Folder")
				and Node.Parent.Parent
				and Node.Parent.Parent.Name == "Pumpkins"
			then
				return Node
			end
			Node = Node.Parent
		end
		return Named
	end
	function A0Features.UpdateUtil.Trap(Object, Tags)
		if not Object or not Object.Parent then
			return nil
		end
		local Node = Object
		for _ = 1, 4 do
			if not Node or Node == workspace then
				break
			end
			if Node.Name == "BearTrap" or (Tags and Tags:HasTag(Node, "BearTrap")) then
				return Node
			end
			Node = Node.Parent
		end
	end
	function A0Features.UpdateUtil.AngleHit(PreviousLocal, CurrentLocal, GoalLocal)
		local Relative = (CurrentLocal - GoalLocal) % 360
		if Relative >= 104 and Relative <= 114 then
			return true
		end
		if PreviousLocal == nil then
			return false
		end
		local StepLocal = (CurrentLocal - PreviousLocal + 180) % 360 - 180
		if math.abs(StepLocal) > 120 or math.abs(StepLocal) < 0.001 then
			return false
		end
		if StepLocal > 0 then
			return (GoalLocal + 104 - PreviousLocal) % 360 <= StepLocal
		end
		return (PreviousLocal - GoalLocal - 114) % 360 <= -StepLocal
	end
	function A0Features.SolveLinearIntercept(Vector, OriginLocal, TargetLocal, VelocityLocal, SpeedLocal)
		if type(SpeedLocal) ~= "number" or SpeedLocal <= 0 or SpeedLocal ~= SpeedLocal or SpeedLocal == math.huge then
			return nil
		end
		local Delta = TargetLocal - OriginLocal
		if Delta.Magnitude < 0.001 then
			return nil
		end
		local ValueLocal36, ValueLocal37, ValueLocal38 =
			VelocityLocal:Dot(VelocityLocal) - SpeedLocal * SpeedLocal, 2 * Delta:Dot(VelocityLocal), Delta:Dot(Delta)
		local DurationLocal
		if math.abs(ValueLocal36) < 1e-7 then
			if math.abs(ValueLocal37) > 1e-7 then
				local ValueLocal39 = -ValueLocal38 / ValueLocal37
				if ValueLocal39 > 0 then
					DurationLocal = ValueLocal39
				end
			end
		else
			local Discriminant = ValueLocal37 * ValueLocal37 - 4 * ValueLocal36 * ValueLocal38
			if Discriminant >= 0 then
				local RootLocal = math.sqrt(Discriminant)
				local ValueLocal39 = -0.5 * (ValueLocal37 + (ValueLocal37 >= 0 and RootLocal or -RootLocal))
				local ValueLocal40 = ValueLocal39 / ValueLocal36
				local ValueLocal41 = math.abs(ValueLocal39) > 1e-12 and ValueLocal38 / ValueLocal39
					or (-ValueLocal37 + RootLocal) / (2 * ValueLocal36)
				if ValueLocal40 > 0 then
					DurationLocal = ValueLocal40
				end
				if ValueLocal41 > 0 and (not DurationLocal or ValueLocal41 < DurationLocal) then
					DurationLocal = ValueLocal41
				end
			end
		end
		if not DurationLocal or DurationLocal > 8 then
			return nil
		end
		local Impact = TargetLocal + VelocityLocal * DurationLocal
		return (Impact - OriginLocal).Unit, Impact, DurationLocal
	end
	function A0Features.CreateWorldAdapter(Deps)
		local Api = { Pumpkins = {}, Traps = {}, NPCs = {}, Proxies = {}, NextID = 0, Destroyed = false }
		local Util = A0Features.UpdateUtil
		function Api:Add(Object)
			if self.Destroyed or not Object or not Object.Parent then
				return
			end
			local PumpkinLocal = Util.Pumpkin(Object)
			if PumpkinLocal then
				self.Pumpkins[PumpkinLocal] = true
			end
			local TrapLocal = Util.Trap(Object, Deps.tags)
			if TrapLocal then
				self.Traps[TrapLocal] = true
			end
			local Node = Object
			for _ = 1, 4 do
				if not Node or Node == Deps.world then
					break
				end
				if
					Node:IsA("Model")
					and Node:FindFirstChildOfClass("Humanoid")
					and Node:FindFirstChild("HumanoidRootPart")
				then
					self.NPCs[Node] = true
					break
				end
				Node = Node.Parent
			end
		end
		function Api:Remove(Object)
			self.Pumpkins[Object], self.Traps[Object], self.NPCs[Object] = nil, nil, nil
			local Proxy = self.Proxies[Object]
			if Proxy then
				Deps.removePlayer(Proxy)
				self.Proxies[Object] = nil
			end
		end
		function Api:List(SetLocal)
			local ListLocal = {}
			for Object in pairs(SetLocal) do
				if Object.Parent and Object:IsDescendantOf(Deps.world) then
					ListLocal[#ListLocal + 1] = Object
				else
					self:Remove(Object)
				end
			end
			return ListLocal
		end
		function Api:GetESPPlayers()
			local ListLocal = Deps.players()
			if not Deps.settings().BotESP.Enabled then
				for Model, Proxy in pairs(self.Proxies) do
					Deps.removePlayer(Proxy)
					self.Proxies[Model] = nil
				end
				return ListLocal
			end
			local Owned = {}
			for _, PlayerLocal in ipairs(ListLocal) do
				if PlayerLocal.Character then
					Owned[PlayerLocal.Character] = true
				end
			end
			for Model in pairs(self.NPCs) do
				local HumanoidLocal = Model.Parent and Model:FindFirstChildOfClass("Humanoid")
				local RootLocal = Model.Parent and Model:FindFirstChild("HumanoidRootPart")
				local ValidLocal = HumanoidLocal
					and RootLocal
					and Model:IsDescendantOf(Deps.world)
					and not Owned[Model]
					and not Model.Name:lower():match("^scp%d*$")
					and tonumber(Model:GetAttribute("Cured")) ~= 3
				if
					ValidLocal
					and Deps.settings().BotESP.Enabled
					and (
						HumanoidLocal.Health > 0
						or Model:GetAttribute("Knocked") == true
						or Model:GetAttribute("IsHooked") == true
					)
				then
					local Role = (
						Model.Parent.Name == "Killers"
						or Model:FindFirstChild("StunEvent")
						or Model:GetAttribute("Role") == "Killer"
						or Model:GetAttribute("IsKiller") == true
						or Model.Name == "Veil"
					)
							and "Killer"
						or "Survivors"
					local Proxy = self.Proxies[Model]
					if not Proxy then
						self.NextID += 1
						Proxy = {
							IsBot = true,
							Character = Model,
							UserId = -self.NextID,
							Team = { Name = Role },
							Name = Model.Name,
							DisplayName = Model.Name .. " [Bot]",
						}
						function Proxy:IsA(Class)
							return Class == "Player"
						end
						function Proxy:GetAttribute(KeyLocal)
							return self.Character:GetAttribute(KeyLocal)
						end
						function Proxy:FindFirstChild(KeyLocal)
							return self.Character:FindFirstChild(KeyLocal)
						end
						self.Proxies[Model] = Proxy
					end
					Proxy.Name, Proxy.DisplayName, Proxy.Team.Name = Model.Name, Model.Name .. " [Bot]", Role
					ListLocal[#ListLocal + 1] = Proxy
				else
					local Proxy = self.Proxies[Model]
					if Proxy then
						Deps.removePlayer(Proxy)
						self.Proxies[Model] = nil
					end
					if not Model.Parent or not Model:IsDescendantOf(Deps.world) then
						self.NPCs[Model] = nil
					end
				end
			end
			return ListLocal
		end
		function Api:Scan()
			local Queue, Head, Visited = { Deps.world }, 1, 0
			local SliceStarted = os.clock()
			while Head <= #Queue and not self.Destroyed and Deps.alive() do
				local Node = Queue[Head]
				Queue[Head] = false
				Head += 1
				for _, Child in ipairs(Node:GetChildren()) do
					if self.Destroyed or not Deps.alive() then
						return
					end
					Queue[#Queue + 1] = Child
					self:Add(Child)
					Visited += 1
					if Visited % 32 == 0 and os.clock() - SliceStarted >= 0.002 then
						Deps.yield()
						SliceStarted = os.clock()
					end
				end
			end
		end
		function Api:Destroy()
			self.Destroyed = true
			for _, Proxy in pairs(self.Proxies) do
				Deps.removePlayer(Proxy)
			end
			table.clear(self.Proxies)
			table.clear(self.NPCs)
			table.clear(self.Pumpkins)
			table.clear(self.Traps)
		end
		return Api
	end

	function A0Features.EnsureFarmHeal()
		if SettingsLocal1.InstantHeal then
			return
		end
		SettingsLocal1.InstantHeal = true
		local Control = controlRegistry and controlRegistry.InstantHeal
		if Control and Control.setValue then
			pcall(Control.setValue, true, false)
		end
		if A0Features.InstantRecovery then
			A0Features.InstantRecovery:Reset()
		end
		pcall(saveSettings)
	end
	function A0Features.CreateFarmPresentation(Deps)
		local Api = {
			Destroyed = false,
			SprintHeld = false,
			Point = nil,
			Character = nil,
			Track = nil,
			NextAssetScan = 0,
			Status = "Idle",
			Generation = 0,
		}
		function Api:SetRunning(Enabled)
			Enabled = Enabled == true and not self.Destroyed and Deps.alive()
			if Enabled == self.SprintHeld then
				return
			end
			if Enabled then
				self.SprintHeld = pcall(Deps.sprint, true)
			else
				self.SprintHeld = false
				pcall(Deps.sprint, false)
			end
		end
		function Api:StopRepair()
			self.Generation += 1
			self.Point = nil
			if self.Track then
				pcall(function()
					self.Track:Stop(0.18)
					self.Track:Destroy()
				end)
				self.Track = nil
			end
			if self.RotatingHumanoid and self.RotatingHumanoid.Parent and self.RotatingHumanoid.AutoRotate == false then
				self.RotatingHumanoid.AutoRotate = self.PreviousAutoRotate
			end
			self.RotatingHumanoid, self.PreviousAutoRotate = nil, nil
		end
		function Api:Reset()
			self:SetRunning(false)
			self:StopRepair()
			self.Character, self.AnimationId = nil, nil
			self.NextAssetScan = 0
		end
		function Api:FindRepairAnimation(Point, Character, Generation)
			if self.AnimationId then
				return self.AnimationId
			end
			if Deps.clock() < self.NextAssetScan then
				return nil
			end
			self.NextAssetScan = Deps.clock() + 30
			local Roots = { Point.Parent, Character }
			local Storage = Deps.storage
			local Assets = Storage and (Storage:FindFirstChild("Animations") or Storage:FindFirstChild("Assets"))
			if Assets then
				Roots[#Roots + 1] = Assets
			elseif Storage then
				Roots[#Roots + 1] = Storage
			end
			local Queue, Seen, Head, Visited = {}, {}, 1, 0
			for _, Root in ipairs(Roots) do
				if Root and not Seen[Root] then
					Seen[Root] = true
					Queue[#Queue + 1] = Root
				end
			end
			local Id, Score = nil, 0
			while Head <= #Queue and Visited < 4096 do
				if
					self.Destroyed
					or not Deps.alive()
					or self.Generation ~= Generation
					or Deps.player.Character ~= Character
				then
					return nil
				end
				local Object = Queue[Head]
				Queue[Head] = false
				Head += 1
				Visited += 1
				if Object:IsA("Animation") and Object.AnimationId ~= "" then
					local Name, Parent, Depth = Object.Name:lower(), Object.Parent, 0
					while Parent and Depth < 4 do
						Name ..= "/" .. Parent.Name:lower()
						Parent, Depth = Parent.Parent, Depth + 1
					end
					local Value = Name:find("repair", 1, true) and 10 or 0
					if Name:find("generator", 1, true) and Value > 0 then
						Value += 10
					end
					if Name:find("loop", 1, true) then
						Value += Value > 0 and 2 or 0
					end
					if Name:find("killer", 1, true) or Name:find("fail", 1, true) or Name:find("end", 1, true) then
						Value = 0
					end
					if Value > Score then
						Id, Score = Object.AnimationId, Value
					end
				end
				for _, Child in ipairs(Object:GetChildren()) do
					if not Seen[Child] and #Queue < 4096 then
						Seen[Child] = true
						Queue[#Queue + 1] = Child
					end
				end
				if Visited % 64 == 0 then
					Deps.yield()
				end
			end
			if self.Generation == Generation and Deps.player.Character == Character then
				self.AnimationId = Id
			end
			return Id
		end
		function Api:BeginRepair(Point)
			if self.Destroyed or not Deps.alive() or not Point or not Point.Parent then
				return false
			end
			local Character = Deps.player.Character
			if self.Character ~= Character then
				self:Reset()
				self.Character = Character
			end
			if self.Point == Point then
				return true
			end
			self:StopRepair()
			self:SetRunning(false)
			local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
			local Root = Character and Character:FindFirstChild("HumanoidRootPart")
			if not Humanoid or not Root or Humanoid.Health <= 0 or (Root.Position - Point.Position).Magnitude > 10 then
				return false
			end
			self.Point = Point
			local Generation = self.Generation
			local Prompt = Point:FindFirstChildWhichIsA("ProximityPrompt", true)
			if Prompt and Prompt.Enabled and Deps.prompt then
				pcall(Deps.prompt, Prompt)
			end
			if not Deps.settings().FarmRepairAnimation then
				self.Status = "Repair interaction started; animation disabled"
				return true
			end
			local AnimationId = self:FindRepairAnimation(Point, Character, Generation)
			if
				self.Generation ~= Generation
				or self.Destroyed
				or Deps.player.Character ~= Character
				or self.Point ~= Point
			then
				return false
			end
			local Animator = Humanoid:FindFirstChildOfClass("Animator")
			if not AnimationId or not Animator then
				self.Status = "Repairing; no replicated repair animation found"
				return true
			end
			local Success, Track = pcall(Deps.load, Animator, AnimationId)
			if Success and Track then
				if
					self.Destroyed
					or self.Generation ~= Generation
					or Deps.player.Character ~= Character
					or self.Point ~= Point
				then
					pcall(Track.Destroy, Track)
					return false
				end
				self.Track = Track
				local Played = pcall(function()
					Track.Priority = Enum.AnimationPriority.Action
					Track.Looped = true
					Track:Play(0.18)
					self.RotatingHumanoid, self.PreviousAutoRotate = Humanoid, Humanoid.AutoRotate
					Humanoid.AutoRotate = false
					local Target = Point.Parent:IsA("Model") and Point.Parent:GetPivot().Position or Point.Position
					local Aim = Vector3.new(Target.X, Root.Position.Y, Target.Z)
					if (Aim - Root.Position).Magnitude > 0.1 then
						Root.CFrame = CFrame.lookAt(Root.Position, Aim)
					end
				end)
				if not Played then
					self:StopRepair()
					self.Status = "Repairing; game animation could not be played"
					return true
				end
				self.Status = "Repairing with game animation"
			else
				self.Status = "Repairing; game animation could not be loaded"
			end
			return true
		end
		function Api:Destroy()
			if self.Destroyed then
				return
			end
			self:Reset()
			self.Destroyed = true
		end
		return Api
	end

	function A0Features.CreateNavigation(Deps)
		local Api = { Generation = 0, Destroyed = false, Busy = false, Status = "Idle", Owner = nil }
		function Api:ReleasePath()
			if self.Blocked then
				pcall(function()
					self.Blocked:Disconnect()
				end)
				self.Blocked = nil
			end
			if self.Path then
				pcall(function()
					self.Path:Destroy()
				end)
				self.Path = nil
			end
		end
		function Api:Cancel()
			self.Generation += 1
			self:ReleasePath()
			if Deps.movement then
				pcall(Deps.movement, false)
			end
			local HumanoidLocal = self.Humanoid
			if HumanoidLocal and HumanoidLocal.Parent then
				pcall(function()
					HumanoidLocal:Move(Vector3.zero, false)
					HumanoidLocal:MoveTo(
						HumanoidLocal.RootPart and HumanoidLocal.RootPart.Position
							or HumanoidLocal.Parent:GetPivot().Position
					)
				end)
			end
		end
		function Api:Move(Destination, OwnerLocal, Allowed)
			if self.Destroyed or not Deps.alive() or not Allowed() or self.Busy then
				return false
			end
			local CharacterLocal = Deps.character()
			local RootLocal = CharacterLocal and CharacterLocal:FindFirstChild("HumanoidRootPart")
			local HumanoidLocal = CharacterLocal and CharacterLocal:FindFirstChildOfClass("Humanoid")
			if not RootLocal or not HumanoidLocal or HumanoidLocal.Health <= 0 then
				return false
			end
			self:Cancel()
			self.Busy = true
			self.Owner = OwnerLocal
			self.Humanoid = HumanoidLocal
			local GenerationLocal = self.Generation
			local TargetLocal = Destination.Position
			local function CurrentLocal()
				return not self.Destroyed
					and Deps.alive()
					and GenerationLocal == self.Generation
					and Allowed()
					and Deps.character() == CharacterLocal
					and RootLocal.Parent ~= nil
					and HumanoidLocal.Health > 0
					and CharacterLocal:GetAttribute("Knocked") ~= true
					and CharacterLocal:GetAttribute("IsHooked") ~= true
			end
			local OriginalLocal = HumanoidLocal.WalkSpeed
			local Running = Deps.settings().FarmRun == true
			local SpeedLocal = Running and math.clamp(tonumber(Deps.settings().FarmRunSpeed) or 24, 16, 30)
				or math.clamp(tonumber(Deps.settings().SafeWalkSpeed) or 16, 14, 24)
			local function Reached(PositionLocal, Tolerance)
				local GapLocal = RootLocal.Position - PositionLocal
				return GapLocal.X * GapLocal.X + GapLocal.Z * GapLocal.Z <= Tolerance * Tolerance
					and math.abs(GapLocal.Y) <= 5
			end
			local Deadline = Deps.clock() + 30
			local SuccessLocal, Result = pcall(function()
				if Reached(TargetLocal, 4) then
					self.Status = "Arrived"
					return CurrentLocal()
				end
				if Deps.settings().AutoFarmMethod == "Legacy Teleport" then
					if CurrentLocal() then
						RootLocal.CFrame = Destination
						self.Status = "Legacy teleport applied"
						return true
					end
					return false
				end
				HumanoidLocal.WalkSpeed = SpeedLocal
				for Attempt = 1, 3 do
					if not CurrentLocal() or Deps.clock() >= Deadline then
						break
					end
					self:ReleasePath()
					self.Status = Attempt == 1 and "Computing path" or "Replanning blocked/stalled path"
					local PathLocal = Deps.pathfinding:CreatePath({
						AgentRadius = 2,
						AgentHeight = 5,
						AgentCanJump = true,
						WaypointSpacing = 4,
					})
					self.Path = PathLocal
					PathLocal:ComputeAsync(RootLocal.Position, TargetLocal)
					if not CurrentLocal() then
						return false
					end
					if PathLocal.Status ~= Enum.PathStatus.Success then
						self.Status = "No path; no teleport fallback"
						return false
					end
					local BlockedLocal, IndexLocal = false, 1
					if PathLocal.Blocked then
						self.Blocked = PathLocal.Blocked:Connect(function(Waypoint)
							if Waypoint >= IndexLocal then
								BlockedLocal = true
							end
						end)
					end
					local Stalled = false
					for Waypoint, PointLocal in ipairs(PathLocal:GetWaypoints()) do
						IndexLocal = Waypoint
						if not CurrentLocal() or BlockedLocal then
							break
						end
						if not Reached(PointLocal.Position, 2.5) then
							if PointLocal.Action == Enum.PathWaypointAction.Jump then
								HumanoidLocal.Jump = true
							end
							if Deps.movement then
								pcall(Deps.movement, Running)
							end
							HumanoidLocal.WalkSpeed = SpeedLocal
							HumanoidLocal:MoveTo(PointLocal.Position)
							self.Status = Running and "Running" or "Walking"
							local Due = math.min(
								Deadline,
								Deps.clock()
									+ math.clamp(
										(RootLocal.Position - PointLocal.Position).Magnitude / SpeedLocal + 2,
										2,
										8
									)
							)
							local LastPosition, LastProgress = RootLocal.Position, Deps.clock()
							while not Reached(PointLocal.Position, 2.5) do
								if not CurrentLocal() then
									self.Status = "Walk cancelled"
									return false
								end
								if BlockedLocal then
									break
								end
								if HumanoidLocal.WalkSpeed ~= SpeedLocal then
									HumanoidLocal.WalkSpeed = SpeedLocal
								end
								if Deps.clock() >= Due then
									Stalled = true
									break
								end
								if (RootLocal.Position - LastPosition).Magnitude >= 0.6 then
									LastPosition, LastProgress = RootLocal.Position, Deps.clock()
								elseif Deps.clock() - LastProgress >= 1.25 then
									HumanoidLocal.Jump = true
									Stalled = true
									break
								end
								Deps.yield(0.05)
							end
						end
						if BlockedLocal or Stalled then
							break
						end
					end
					if CurrentLocal() and Reached(TargetLocal, 5) then
						self.Status = "Arrived"
						return true
					end
					if not BlockedLocal and not Stalled then
						self.Status = "Path ended short of destination"
					end
				end
				self.Status = CurrentLocal() and "Path retries exhausted; no teleport fallback" or "Walk cancelled"
				return false
			end)
			self:ReleasePath()
			if Deps.movement then
				pcall(Deps.movement, false)
			end
			if HumanoidLocal.Parent and HumanoidLocal.WalkSpeed == SpeedLocal then
				HumanoidLocal.WalkSpeed = OriginalLocal
			end
			if (not SuccessLocal or not Result) and CharacterLocal == Deps.character() and HumanoidLocal.Parent then
				pcall(function()
					HumanoidLocal:Move(Vector3.zero, false)
					HumanoidLocal:MoveTo(RootLocal.Position)
				end)
			end
			self.Busy, self.Humanoid, self.Owner = false, nil, nil
			if not SuccessLocal then
				self.Status = "Navigation error: " .. tostring(Result)
			end
			return SuccessLocal and Result == true
		end
		function Api:Destroy()
			self.Destroyed = true
			self:Cancel()
		end
		return Api
	end
	function A0Features.CreateTrapAdapter(Deps)
		local Api = {
			Check = nil,
			Goal = nil,
			Line = nil,
			Previous = nil,
			GoalRotation = nil,
			Sent = false,
			Last = 0,
			Destroyed = false,
			Status = "Waiting for Bear Trap check",
		}
		function Api:Find()
			if self.Destroyed then
				return
			end
			local GuiLocal = Deps.gui()
			if not GuiLocal then
				return
			end
			for _, NameLocal in ipairs({ "SkillCheckPromptGui", "SkillCheckPromptGui-con" }) do
				local Screen = GuiLocal:FindFirstChild(NameLocal)
				local CheckLocal = Screen
					and Screen:IsA("ScreenGui")
					and Screen.Enabled
					and Screen:FindFirstChild("Check")
				if CheckLocal and CheckLocal.Visible then
					local Perfect, GoalLocal =
						CheckLocal:FindFirstChild("TrapPerfect"), CheckLocal:FindFirstChild("TrapGoal")
					local TargetLocal = (Perfect and Perfect.Visible and Perfect)
						or (GoalLocal and GoalLocal.Visible and GoalLocal)
					local LineLocal = CheckLocal:FindFirstChild("Line")
					if TargetLocal and LineLocal then
						return CheckLocal, LineLocal, TargetLocal
					end
				end
			end
		end
		function Api:IsTrapActive()
			return self:Find() ~= nil
		end
		function Api:Step()
			if self.Destroyed or not Deps.alive() then
				return
			end
			local Settings = Deps.settings()
			if not Settings.AutoSkillCheck or not Settings.TrapAutoSkillCheck then
				self.Check, self.Line, self.Goal, self.Previous = nil, nil, nil, nil
				self.Sent = false
				return
			end
			local CheckLocal, LineLocal, GoalLocal = self:Find()
			if not CheckLocal then
				self.Check, self.Line, self.Goal, self.Previous = nil, nil, nil, nil
				self.Sent = false
				return
			end
			local RotationLocal = GoalLocal.Rotation
			if
				self.Check ~= CheckLocal
				or self.Line ~= LineLocal
				or self.Goal ~= GoalLocal
				or self.GoalRotation ~= RotationLocal
			then
				self.Check, self.Line, self.Goal, self.GoalRotation = CheckLocal, LineLocal, GoalLocal, RotationLocal
				self.Previous = nil
				self.Sent = false
				self.Last = 0
			end
			local Now = Deps.clock()
			local Relative = (LineLocal.Rotation - RotationLocal) % 360
			local Inside = Relative >= 104 and Relative <= 114
			if self.Sent and not Inside and Now - self.Last > 0.18 then
				self.Sent = false
			end
			local Hit = A0Features.UpdateUtil.AngleHit(self.Previous, LineLocal.Rotation, RotationLocal)
			self.Previous = LineLocal.Rotation
			if Hit and not self.Sent and Now - self.Last > 0.08 then
				self.Sent = true
				self.Last = Now
				local SuccessLocal = Deps.send()
				self.Status = SuccessLocal and "Bear Trap input dispatched (result unverified)"
					or "Bear Trap input unavailable"
			end
		end
		function Api:Destroy()
			self.Destroyed = true
			self.Check, self.Line, self.Goal = nil, nil, nil
		end
		return Api
	end

	function A0Features.CreateInputAdapter(Deps)
		local Api = { Busy = false, Destroyed = false, Status = "Waiting for input" }
		function Api:Visible(Object)
			if not Object or not Object.Parent then
				return false
			end
			local Node = Object
			while Node and Node ~= Deps.gui() do
				if Node:IsA("GuiObject") and not Node.Visible then
					return false
				end
				if Node:IsA("ScreenGui") and not Node.Enabled then
					return false
				end
				Node = Node.Parent
			end
			return Node ~= nil
		end
		function Api:Button(ButtonLocal)
			if
				self.Destroyed
				or not Deps.alive()
				or not ButtonLocal
				or not ButtonLocal:IsA("GuiButton")
				or not self:Visible(ButtonLocal)
				or ButtonLocal.Active == false
			then
				return false
			end

			for _, KeyLocal in ipairs({ "Activated", "MouseButton1Down", "MouseButton1Click" }) do
				local Signal = ButtonLocal[KeyLocal]
				if Deps.connections then
					local SuccessLocal, ListLocal = pcall(Deps.connections, Signal)
					local SentLocal = false
					if SuccessLocal and type(ListLocal) == "table" then
						for _, ConnectionLocal in pairs(ListLocal) do
							if ConnectionLocal.Connected ~= false and ConnectionLocal.Enabled ~= false then
								local Fired = false
								if type(ConnectionLocal.Fire) == "function" then
									Fired = pcall(function()
										ConnectionLocal:Fire()
									end)
								elseif type(ConnectionLocal.Function) == "function" then
									Fired = pcall(ConnectionLocal.Function)
								end
								SentLocal = SentLocal or Fired
							end
						end
					end
					if SentLocal then
						self.Status = "GUI action dispatched"
						return true
					end
				end
			end
			if not Deps.connections and Deps.fire then
				local SuccessLocal = pcall(Deps.fire, ButtonLocal.Activated)
				if SuccessLocal then
					self.Status = "GUI Activated requested (listener unverified)"
					return true
				end
			end
			return false
		end
		function Api:Action(NameLocal)
			local GuiLocal = Deps.gui()
			if not GuiLocal then
				return false
			end
			for _, ScreenName in ipairs({ "Survivor-mob", "Survivor-con", "Survivor" }) do
				local Screen = GuiLocal:FindFirstChild(ScreenName)
				local Controls = Screen and Screen:FindFirstChild("Controls")
				local ButtonLocal = Controls and Controls:FindFirstChild(NameLocal)
				if ButtonLocal and self:Visible(ButtonLocal) then
					if self:Button(ButtonLocal) then
						return true
					end
					for _, Child in ipairs(ButtonLocal:GetChildren()) do
						if self:Button(Child) then
							return true
						end
					end
				end
			end
			return false
		end
		function Api:Key(Code)
			if self.Destroyed or not Deps.alive() then
				return false
			end
			local Pressed = pcall(Deps.key, true, Code)
			if Pressed then
				Deps.delay(0.025, function()
					pcall(Deps.key, false, Code)
				end)
				self.Status = "Key press/release requested"
			end
			return Pressed
		end
		function Api:Skill(Prompt)
			if self.Destroyed or self.Busy or not Deps.alive() or not Deps.settings().AutoSkillCheck then
				return false
			end
			self.Busy = true
			local SuccessLocal, SentLocal = pcall(function()
				local GuiLocal = Deps.gui()
				if not GuiLocal then
					return false
				end
				if not Prompt or not self:Visible(Prompt) then
					Prompt = nil
					for _, NameLocal in ipairs({ "SkillCheckPromptGui", "SkillCheckPromptGui-con" }) do
						local Candidate = GuiLocal:FindFirstChild(NameLocal)
						local CheckLocal = Candidate and Candidate:FindFirstChild("Check")
						if Candidate and self:Visible(Candidate) and CheckLocal and self:Visible(CheckLocal) then
							Prompt = Candidate
							break
						end
					end
				end
				local CheckLocal = Prompt and Prompt:FindFirstChild("Check")
				if not CheckLocal or not self:Visible(CheckLocal) then
					return false
				end
				if Deps.touch() then
					if self:Action("action") then
						return true
					end
					for _, NameLocal in ipairs({ "action", "Action", "interact", "Interact", "Space", "Use", "check" }) do
						local ButtonLocal = CheckLocal:FindFirstChild(NameLocal, true)
						if self:Button(ButtonLocal) then
							return true
						end
					end
					for _, ButtonLocal in ipairs(CheckLocal:GetDescendants()) do
						if self:Button(ButtonLocal) then
							return true
						end
					end
					self.Status = "Visible mobile action listener unavailable"
					return false
				end
				if Deps.native() then
					return true
				end
				return self:Key(
					Prompt.Name == "SkillCheckPromptGui-con" and Enum.KeyCode.ButtonL1 or Enum.KeyCode.Space
				)
			end)
			self.Busy = false
			if not SuccessLocal then
				self.Status = "Input dispatch failed"
			end
			return SuccessLocal and SentLocal == true
		end
		function Api:Pumpkin()
			local GuiLocal = Deps.gui()
			local Screen = GuiLocal and GuiLocal:FindFirstChild("pcprompts")
			local FrameLocal = Screen and Screen:FindFirstChild("Frame")
			local Prompt = FrameLocal and FrameLocal:FindFirstChild("pumpkinstomp")
			if not self:Visible(Prompt) then
				return false
			end
			if self:Button(Prompt) then
				return true
			end
			for _, Child in ipairs(Prompt:GetChildren()) do
				if self:Button(Child) then
					return true
				end
			end
			if not Deps.touch() then
				return self:Key(Enum.KeyCode.Space)
			end
			return self:Action("action")
		end
		function Api:Destroy()
			self.Destroyed = true
		end
		return Api
	end
	function A0Features.CreateVaultAdapter(Deps)
		local Api = {
			Destroyed = false,
			Controller = nil,
			Patches = {},
			Session = nil,
			Manual = false,
			Status = "Waiting for vault controller",
		}
		function Api:Patch(ModuleLocal, KeyLocal)
			if type(ModuleLocal) ~= "table" or type(ModuleLocal[KeyLocal]) ~= "function" then
				return
			end
			for _, PatchLocal in ipairs(self.Patches) do
				if PatchLocal.Module == ModuleLocal and PatchLocal.Key == KeyLocal then
					return
				end
			end
			local OriginalLocal = ModuleLocal[KeyLocal]
			local WrappedLocal = function(...)
				if not self.Destroyed and Deps.alive() and Deps.settings().AlwaysFastVault then
					return true, "ready", 5
				end
				return OriginalLocal(...)
			end
			ModuleLocal[KeyLocal] = WrappedLocal
			self.Patches[#self.Patches + 1] =
				{ Module = ModuleLocal, Key = KeyLocal, Original = OriginalLocal, Wrapped = WrappedLocal }
		end
		function Api:Warm()
			if
				self.Destroyed
				or not Deps.alive()
				or not (Deps.settings().AlwaysFastVault or Deps.settings().FakeVault or self.Manual)
			then
				return
			end
			local Modules, ControllerLocal = Deps.discover()
			if self.Destroyed or not Deps.alive() then
				return
			end
			for _, EntryLocal in ipairs(Modules or {}) do
				self:Patch(EntryLocal[1], EntryLocal[2])
			end
			self.Controller = ControllerLocal
			if ControllerLocal then
				self:Patch(ControllerLocal, "_validateFastVault")
				self.Status = "Vault controller ready"
			end
		end
		function Api:Finish(SessionLocal)
			local ValueLocal36 = SessionLocal.Controller
			local CancelLocal = SessionLocal.Slide and ValueLocal36._cancelSlideTraversal
				or ValueLocal36._cancelVaultTraversal
			if type(CancelLocal) ~= "function" then
				self.Status = "Traversal cancellation unavailable"
				return false
			end
			local SuccessLocal = pcall(CancelLocal, ValueLocal36)
			if not SuccessLocal then
				self.Status = "Traversal cancellation failed"
				return false
			end
			if Deps.character() == SessionLocal.Character and SessionLocal.Root.Parent then
				SessionLocal.Root.CFrame = SessionLocal.Entry * CFrame.new(0, 0, 0.5)
				SessionLocal.Root.AssemblyLinearVelocity = Vector3.zero
				SessionLocal.Root.AssemblyAngularVelocity = Vector3.zero
				SessionLocal.Character:SetAttribute("overridelookscript", false)
				SessionLocal.Character:SetAttribute("isVaulting", false)
				SessionLocal.Character:SetAttribute("isSliding", false)
				if SessionLocal.Humanoid and SessionLocal.Humanoid.Parent then
					SessionLocal.Humanoid.AutoRotate = SessionLocal.AutoRotate
					SessionLocal.Humanoid.JumpPower = SessionLocal.JumpPower
				end
			end
			self.Status = "Fake vault cancelled and returned to entry"
			return true
		end
		function Api:Trigger()
			if self.Destroyed or not Deps.alive() then
				return false
			end
			self.Manual = true
			if self.Session and not self.Session.Done then
				self.Session.Done = self:Finish(self.Session)
				self.Manual = false
				return self.Session.Done
			end
			local Actions = Deps.actions()
			if not Actions then
				self.Status = "Survivor actions unavailable"
				self.Manual = false
				return false
			end
			local SuccessLocal = false
			if type(Actions.startVault) == "function" then
				SuccessLocal = pcall(Actions.startVault)
			end

			local ControllerLocal = self.Controller
			if
				not (ControllerLocal and ControllerLocal.isVaulting)
				and type(Actions.startPalletSlide) == "function"
			then
				SuccessLocal = pcall(Actions.startPalletSlide) or SuccessLocal
			end
			self.ManualUntil = Deps.clock() + 2.5
			return SuccessLocal
		end
		function Api:Step()
			if self.Destroyed or not Deps.alive() then
				return
			end
			if self.ManualUntil and Deps.clock() > self.ManualUntil then
				self.Manual = false
				self.ManualUntil = nil
			end
			local CharacterLocal = Deps.character()
			local RootLocal = CharacterLocal and CharacterLocal:FindFirstChild("HumanoidRootPart")
			local ValueLocal36 = self.Controller
			if ValueLocal36 and ValueLocal36.character and ValueLocal36.character ~= CharacterLocal then
				self.Controller = nil
				ValueLocal36 = nil
			end
			local RunningLocal = ValueLocal36
				and (ValueLocal36.isVaulting == true or ValueLocal36.isSlideingPallet == true)
			if not RunningLocal or not RootLocal then
				self.Session = nil
				return
			end
			local SessionLocal = self.Session
			if
				not SessionLocal
				or SessionLocal.Character ~= CharacterLocal
				or SessionLocal.Controller ~= ValueLocal36
			then
				local HumanoidLocal = CharacterLocal:FindFirstChildOfClass("Humanoid")
				local SlideLocal = ValueLocal36.isSlideingPallet == true
				local EntryLocal = (SlideLocal and ValueLocal36.slideEntryCFrame or ValueLocal36.vaultEntryCFrame)
					or RootLocal.CFrame
				local Wall = SlideLocal and (ValueLocal36.activeSlideWall or ValueLocal36.activeSlidePoint)
					or (ValueLocal36.activeVaultWall or ValueLocal36.activeVaultPoint or ValueLocal36.activeVaultBottom)
				local TargetLocal = Wall and Wall:IsA("BasePart") and Wall.Position
					or (EntryLocal.Position + EntryLocal.LookVector * 3.5)
				local ForwardLocal = (TargetLocal - EntryLocal.Position) * Vector3.new(1, 0, 1)
				if ForwardLocal.Magnitude < 0.01 then
					ForwardLocal = Vector3.new(0, 0, -1)
				end
				SessionLocal = {
					Character = CharacterLocal,
					Root = RootLocal,
					Controller = ValueLocal36,
					Slide = SlideLocal,
					Entry = EntryLocal,
					Target = TargetLocal,
					Forward = ForwardLocal.Unit,
					Started = Deps.clock(),
					Humanoid = HumanoidLocal,
					AutoRotate = HumanoidLocal and HumanoidLocal.AutoRotate,
					JumpPower = HumanoidLocal and HumanoidLocal.JumpPower,
					Engaged = Deps.settings().FakeVault or self.Manual,
					Done = false,
				}
				self.Session = SessionLocal
			end
			if SessionLocal.Done or not (Deps.settings().FakeVault or self.Manual) then
				return
			end
			SessionLocal.Engaged = true
			local Travelled = (RootLocal.Position - SessionLocal.Entry.Position):Dot(SessionLocal.Forward)
			local Crossed = (RootLocal.Position - SessionLocal.Target):Dot(SessionLocal.Forward)
			if (Travelled >= 1.5 and Crossed >= -0.15) or Deps.clock() - SessionLocal.Started >= 2.2 then
				SessionLocal.Done = self:Finish(SessionLocal)
				self.Manual = false
			end
		end
		function Api:Reset()
			for _, PatchLocal in ipairs(self.Patches) do
				if PatchLocal.Module[PatchLocal.Key] == PatchLocal.Wrapped then
					PatchLocal.Module[PatchLocal.Key] = PatchLocal.Original
				end
			end
			table.clear(self.Patches)
			self.Session = nil
			self.Controller = nil
			self.Manual = false
			self.ManualUntil = nil
		end
		function Api:Destroy()
			self.Destroyed = true
			if self.Session and self.Session.Engaged and not self.Session.Done then
				self:Finish(self.Session)
			end
			for _, PatchLocal in ipairs(self.Patches) do
				if PatchLocal.Module[PatchLocal.Key] == PatchLocal.Wrapped then
					PatchLocal.Module[PatchLocal.Key] = PatchLocal.Original
				end
			end
			table.clear(self.Patches)
			self:Reset()
		end
		return Api
	end
	function A0Features.CreateVeilAdapter(Deps)
		local Api = {
			Destroyed = false,
			ChargeFunction = nil,
			Character = nil,
			Status = "Veil input not sampled",
			Generation = 0,
			Busy = false,
			RetryAt = 0,
			RetryDelay = 4,
			ChargeAt = -math.huge,
		}
		local ChargeKeys = { "spearcharge", "Charge", "SpearCharge", "ChargeProgress", "charge" }
		local function Finite(Argument)
			return type(Argument) == "number" and Argument == Argument and math.abs(Argument) < math.huge
		end
		local function Vector(Argument)
			return Deps.typeof(Argument) == "Vector3"
				and Finite(Argument.X)
				and Finite(Argument.Y)
				and Finite(Argument.Z)
		end
		function Api:Warm()
			local CharacterLocal = Deps.character()
			local AnimationScript = CharacterLocal and CharacterLocal:FindFirstChild("Animations")
			if self.Character ~= CharacterLocal or self.AnimationScript ~= AnimationScript then
				self:Reset()
				self.Character, self.AnimationScript = CharacterLocal, AnimationScript
			end
			if
				self.Destroyed
				or not Deps.alive()
				or not CharacterLocal
				or self.ChargeFunction
				or self.Busy
				or Deps.clock() < self.RetryAt
			then
				return
			end
			self.Busy = true
			local Generation = self.Generation
			local Success, Found = pcall(Deps.discover, CharacterLocal)
			if Generation ~= self.Generation then
				return
			end
			self.Busy = false
			if self.Destroyed or not Deps.alive() or Deps.character() ~= CharacterLocal then
				return
			end
			if Success and type(Found) == "function" then
				self.ChargeFunction = Found
				self.RetryDelay = 4
			else
				self.RetryAt = Deps.clock() + self.RetryDelay
				self.RetryDelay = math.min(self.RetryDelay * 2, 16)
			end
		end
		function Api:ReadCharge()
			local CharacterLocal = Deps.character()
			local Now = Deps.serverTime()
			if CharacterLocal and CharacterLocal == self.Character and self.ChargeFunction and Deps.upvalues then
				local SuccessLocal, Values14 = pcall(Deps.upvalues, self.ChargeFunction)
				if
					SuccessLocal
					and type(Values14) == "table"
					and Values14[2] == true
					and Finite(Values14[9])
					and Values14[9] > 0
					and Values14[9] <= Now
				then
					return math.clamp(Now - Values14[9], 0.3, 2), true
				end
			end
			if CharacterLocal then
				for _, KeyLocal in ipairs(ChargeKeys) do
					local ValueLocal36 = CharacterLocal:GetAttribute(KeyLocal)
					if Finite(ValueLocal36) then
						if ValueLocal36 > 1 then
							ValueLocal36 = ValueLocal36 / 100
						end
						return math.clamp(ValueLocal36, 0.3, 1), true
					end
				end
				if CharacterLocal:GetAttribute("spearmode") == true or Deps.playerCharging() then
					if not self.Start then
						self.Start = Deps.clock()
					end
					return math.clamp(Deps.clock() - self.Start, 0.3, 2), true
				end
			end
			self.Start = nil
			return 1, false
		end
		function Api:Charge()
			if self.Destroyed or not Deps.alive() then
				return 1, false
			end
			local Now, CharacterLocal = Deps.clock(), Deps.character()
			if self.ChargeCharacter == CharacterLocal and Now - self.ChargeAt < 1 / 60 then
				return self.ChargeValue, self.Charging
			end
			self.ChargeValue, self.Charging = self:ReadCharge()
			self.ChargeAt, self.ChargeCharacter = Now, CharacterLocal
			return self.ChargeValue, self.Charging
		end
		function Api:Speed()
			local ChargeLocal = self:Charge()
			return math.clamp(ChargeLocal * 180, 1, 180)
		end
		function Api:Origin()
			local CameraLocal = Deps.camera()
			return CameraLocal and CameraLocal.CFrame.Position + CameraLocal.CFrame.LookVector * 3
		end
		function Api:Parameters(Args)
			local PayloadLocal = Args[1]
			if Deps.typeof(PayloadLocal) == "table" then
				local OriginLocal = PayloadLocal.Origin or self:Origin()
				if not Vector(PayloadLocal.Direction) or not Vector(OriginLocal) then
					return nil, "Invalid table spear payload"
				end
				local SpeedLocal = self:Speed()
				if PayloadLocal.Velocity ~= nil then
					if not Vector(PayloadLocal.Velocity) or PayloadLocal.Velocity.Magnitude < 0.01 then
						return nil, "Invalid table spear velocity"
					end
					SpeedLocal = PayloadLocal.Velocity.Magnitude
				elseif PayloadLocal.Speed ~= nil then
					if not Finite(PayloadLocal.Speed) or PayloadLocal.Speed <= 0 then
						return nil, "Invalid table spear speed"
					end
					SpeedLocal = PayloadLocal.Speed
				end
				return { Schema = "Table", Origin = OriginLocal, Speed = SpeedLocal, Payload = PayloadLocal }
			end
			if not Vector(PayloadLocal) then
				return nil, "Unexpected spear direction"
			end
			if Vector(Args[2]) then
				return { Schema = "OriginDirection", Origin = PayloadLocal, Speed = self:Speed() }
			end
			if Args[2] ~= nil and (not Finite(Args[2]) or Args[2] <= 0) then
				return nil, "Invalid legacy speed"
			end
			if Args[2] == nil and type(Args.n) == "number" and Args.n > 1 then
				return nil, "Sparse legacy payload"
			end
			if Args[3] ~= nil and not Vector(Args[3]) then
				return nil, "Invalid legacy origin"
			end
			return { Schema = "Legacy", Origin = Args[3] or self:Origin(), Speed = Args[2] or self:Speed() }
		end
		function Api:Solve(PartLocal, OriginLocal, SpeedLocal)
			if not PartLocal or not OriginLocal then
				return
			end
			local SettingsLocal = Deps.settings()
			local SilentLocal = SettingsLocal.SpearSilentAim or {}
			local Aim = SettingsLocal.SpearAimbot or {}
			local VelocityLocal = PartLocal.AssemblyLinearVelocity or Vector3.zero
			if A0Features.Motion then
				VelocityLocal = A0Features.Motion:Sample(PartLocal.Parent, VelocityLocal, PartLocal)
			end
			local Lead = math.clamp(tonumber(Aim.PredictionOffset) or tonumber(Deps.latency()) or 0.045, 0, 0.25)
			VelocityLocal = Vector3.new(VelocityLocal.X, math.clamp(VelocityLocal.Y, -14, 14), VelocityLocal.Z)
			local TargetLocal = PartLocal.Position
				+ Vector3.new(0, 0.2 + (tonumber(SilentLocal.VerticalOffset) or 0), 0)
				+ VelocityLocal * Lead
			local GravityLocal = tonumber(Aim.Gravity) or 98
			if GravityLocal == 98 then
				GravityLocal = 98.099998474121
			end
			return A0Features.SolveIntercept(
				Vector3.new,
				OriginLocal,
				TargetLocal,
				VelocityLocal,
				Vector3.zero,
				SpeedLocal,
				GravityLocal
			)
		end
		function Api:Apply(Args, ParametersLocal, DirectionLocal)
			if not Vector(DirectionLocal) or DirectionLocal.Magnitude < 0.01 then
				return false
			end
			if ParametersLocal.Schema == "Table" then
				local Copy = table.clone(ParametersLocal.Payload)
				Copy.Direction = DirectionLocal
				Copy.Origin = ParametersLocal.Origin
				if Copy.Velocity ~= nil then
					Copy.Velocity = DirectionLocal * ParametersLocal.Speed
				end
				if Deps.viewDelay then
					local SuccessLocal, Delay = pcall(Deps.viewDelay, ParametersLocal.Origin, DirectionLocal)
					if SuccessLocal and Finite(Delay) then
						Copy.ViewDelay = Delay
					end
				end
				Args[1] = Copy
			elseif ParametersLocal.Schema == "OriginDirection" then
				Args[2] = DirectionLocal
			else
				Args[1] = DirectionLocal
			end
			self.Status = "Veil " .. ParametersLocal.Schema .. " direction updated; hit unverified"
			return true
		end
		function Api:Reset()
			self.Generation += 1
			self.Busy, self.RetryAt, self.RetryDelay = false, 0, 4
			self.ChargeAt, self.ChargeCharacter = -math.huge, nil
			self.ChargeValue, self.Charging, self.AnimationScript = nil, nil, nil
			self.Character = nil
			self.ChargeFunction = nil
			self.Start = nil
		end
		function Api:Destroy()
			self.Destroyed = true
			self:Reset()
		end
		return Api
	end

	function A0Features.CreateNativeAdapter(Deps)
		local Api = {
			Character = nil,
			Inputs = {},
			Client = nil,
			RetryAt = 0,
			Destroyed = false,
			Generation = 0,
			Busy = false,
			SkillStatus = "Not discovered",
			ParryStatus = "Not discovered",
		}
		function Api:Reset()
			self.Generation += 1
			self.Character, self.Client, self.RetryAt = nil, nil, 0
			table.clear(self.Inputs)
		end
		function Api:Equipped(ClientLocal)
			local CharacterLocal = Deps.player.Character
			return CharacterLocal ~= nil
				and ClientLocal
				and ClientLocal.character == CharacterLocal
				and ClientLocal.tool
				and ClientLocal.tool:IsDescendantOf(CharacterLocal)
		end
		function Api:Adopt(ClientLocal)
			if
				self.Destroyed
				or not Deps.alive()
				or type(ClientLocal) ~= "table"
				or type(ClientLocal.Parry) ~= "function"
			then
				return false
			end
			local CharacterLocal = Deps.player.Character
			if
				not CharacterLocal
				or not ClientLocal.tool
				or not ClientLocal.tool:IsDescendantOf(CharacterLocal)
				or (ClientLocal.player ~= nil and ClientLocal.player ~= Deps.player)
			then
				return false
			end
			if ClientLocal.character ~= CharacterLocal and type(ClientLocal._bindCharacter) == "function" then
				pcall(ClientLocal._bindCharacter, ClientLocal, CharacterLocal)
			end
			if not self:Equipped(ClientLocal) then
				return false
			end
			self.Client = ClientLocal
			self.ParryStatus = "Native dagger client ready"
			return true
		end
		function Api:Warm()
			if self.Destroyed or not Deps.alive() or self.Busy then
				return
			end
			local CharacterLocal = Deps.player.Character
			if self.Character ~= CharacterLocal then
				self:Reset()
				self.Character = CharacterLocal
			end
			if not CharacterLocal or Deps.clock() < self.RetryAt then
				return
			end
			self.RetryAt = Deps.clock() + 4
			self.Busy = true
			local GenerationLocal = self.Generation
			local function CurrentLocal()
				return not self.Destroyed
					and Deps.alive()
					and GenerationLocal == self.Generation
					and Deps.player.Character == CharacterLocal
			end
			local SuccessLocal = pcall(function()
				local InputsLocal, Seen = {}, {}
				if Deps.connections and Deps.environment and Deps.wantSkill() then
					local ReadLocal, ListLocal = pcall(Deps.connections, Deps.inputSignal)
					if ReadLocal and type(ListLocal) == "table" then
						local Count = 0
						for _, ConnectionLocal in pairs(ListLocal) do
							if not CurrentLocal() then
								return
							end
							local CallbackLocal = ConnectionLocal.Function
							if
								type(CallbackLocal) == "function"
								and not Seen[CallbackLocal]
								and ConnectionLocal.Connected ~= false
								and ConnectionLocal.Enabled ~= false
							then
								local Found, Environment = pcall(Deps.environment, CallbackLocal)
								local SourceLocal = Found
									and type(Environment) == "table"
									and rawget(Environment, "script")
								if Deps.isScript(SourceLocal, CharacterLocal) then
									InputsLocal[#InputsLocal + 1] =
										{ Callback = CallbackLocal, Source = SourceLocal, Connection = ConnectionLocal }
									Seen[CallbackLocal] = true
								end
							end
							Count += 1
							if Count >= 256 then
								break
							end
							if Count % 8 == 0 then
								Deps.yield()
							end
						end
					end
				end
				if not CurrentLocal() then
					return
				end
				self.Inputs = InputsLocal
				self.SkillStatus = #InputsLocal > 0 and "Native skill input ready"
					or "Native input unavailable; using input fallback"
				if self:Equipped(self.Client) or not Deps.wantParry() or not Deps.connections or not Deps.upvalues then
					return
				end
				self.Client = nil
				local Event = Deps.parryEvent()
				if not Event then
					return
				end
				local ReadLocal, ListLocal = pcall(Deps.connections, Event.OnClientEvent)
				if not ReadLocal or type(ListLocal) ~= "table" then
					return
				end
				local Count = 0
				for _, ConnectionLocal in pairs(ListLocal) do
					if not CurrentLocal() then
						return
					end
					if
						type(ConnectionLocal.Function) == "function"
						and ConnectionLocal.Connected ~= false
						and ConnectionLocal.Enabled ~= false
					then
						local Found, Values14 = pcall(Deps.upvalues, ConnectionLocal.Function)
						if Found and type(Values14) == "table" then
							for _, ClientLocal in pairs(Values14) do
								if CurrentLocal() and self:Adopt(ClientLocal) then
									return
								end
							end
						end
					end
					Count += 1
					if Count >= 256 then
						break
					end
					if Count % 8 == 0 then
						Deps.yield()
					end
				end
				self.ParryStatus = "Native dagger unavailable; using named remote/tool fallback"
			end)
			self.Busy = false
			if not SuccessLocal then
				self.RetryAt = Deps.clock() + 4
			end
		end
		function Api:Skill()
			if self.Destroyed or not Deps.alive() or self.Character ~= Deps.player.Character then
				return false
			end
			local SentLocal = false
			for _, EntryLocal in ipairs(self.Inputs) do
				if
					Deps.isScript(EntryLocal.Source, self.Character)
					and EntryLocal.Connection.Connected ~= false
					and EntryLocal.Connection.Enabled ~= false
				then
					local SuccessLocal = pcall(EntryLocal.Callback, Deps.skillInput(), false)
					SentLocal = SentLocal or SuccessLocal
				end
			end
			if SentLocal then
				self.SkillStatus = "Native skill input dispatched"
			end
			return SentLocal
		end
		function Api:Parry()
			if self.Destroyed or not Deps.alive() or not self:Equipped(self.Client) then
				return false, false
			end
			local ClientLocal = self.Client
			if ClientLocal.isParryOnCooldown or ClientLocal.isParryResolving or ClientLocal.isSilenced then
				self.ParryStatus = "Dagger cooldown, resolving or silenced"
				return true, false
			end
			if type(ClientLocal.CanUse) == "function" then
				local SuccessLocal, ReadyLocal = pcall(ClientLocal.CanUse, ClientLocal)
				if not SuccessLocal then
					self.Client = nil
					return false, false
				end
				if not ReadyLocal then
					self.ParryStatus = "Dagger not ready"
					return true, false
				end
			end
			local SentLocal = pcall(ClientLocal.Parry, ClientLocal)
			self.ParryStatus = SentLocal and "Native dagger input dispatched" or "Native dagger call failed"
			return true, SentLocal
		end
		function Api:Destroy()
			self.Destroyed = true
			self:Reset()
		end
		return Api
	end
	function A0Features.CreateMotion(Deps)
		local Api = { History = setmetatable({}, { __mode = "k" }), NextPrune = 0 }
		function Api:Reset()
			table.clear(self.History)
		end
		function Api:Sample(KeyLocal, Raw, PartLocal)
			local Zero = Deps.vector(0, 0, 0)
			if not KeyLocal then
				return Zero
			end
			if not Raw or Raw.Magnitude ~= Raw.Magnitude or Raw.Magnitude > 100 then
				Raw = Zero
			end
			local Now = Deps.clock()
			if Now >= self.NextPrune then
				self.NextPrune = Now + 2
				for Key, Record in pairs(self.History) do
					if Now - Record.Time > 2 or (Record.Part and not Record.Part.Parent) then
						self.History[Key] = nil
					end
				end
			end
			local PreviousLocal = self.History[KeyLocal]
			local PositionLocal = PartLocal and PartLocal.Position
			if not PreviousLocal or PreviousLocal.Part ~= PartLocal or Now - PreviousLocal.Time > 0.5 then
				self.History[KeyLocal] = { Time = Now, Part = PartLocal, Position = PositionLocal, Velocity = Raw }
				return Raw
			end
			local Elapsed = Now - PreviousLocal.Time
			if Elapsed < 0.04 then
				return PreviousLocal.Velocity
			end
			local Measured = PositionLocal
					and PreviousLocal.Position
					and (PositionLocal - PreviousLocal.Position) / Elapsed
				or Raw
			if Measured.Magnitude > 100 then
				Measured = Raw
			end
			local VelocityLocal = Raw:Lerp(Measured, 0.65)
			local AlphaLocal = 1 - math.exp(-Elapsed * 14)
			PreviousLocal.Velocity = PreviousLocal.Velocity:Lerp(VelocityLocal, AlphaLocal)
			if VelocityLocal.Magnitude < 0.5 then
				PreviousLocal.Velocity = Zero
			end
			PreviousLocal.Time, PreviousLocal.Part, PreviousLocal.Position = Now, PartLocal, PositionLocal
			return PreviousLocal.Velocity
		end
		return Api
	end
	function A0Features.SolveIntercept(
		Vector,
		OriginLocal,
		TargetLocal,
		VelocityLocal,
		Acceleration,
		SpeedLocal,
		GravityLocal
	)
		if type(SpeedLocal) ~= "number" or SpeedLocal <= 0 or SpeedLocal ~= SpeedLocal or SpeedLocal == math.huge then
			return nil
		end
		if type(GravityLocal) ~= "number" or GravityLocal ~= GravityLocal or math.abs(GravityLocal) == math.huge then
			return nil
		end
		local Delta = TargetLocal - OriginLocal
		if Delta.Magnitude < 0.001 then
			return nil
		end
		if VelocityLocal.Magnitude < 0.001 and Acceleration.Magnitude < 0.001 and GravityLocal > 0 then
			local Horizontal2 = Delta.X * Delta.X + Delta.Z * Delta.Z
			local Speed2 = SpeedLocal * SpeedLocal
			local Discriminant = Speed2 * Speed2 - GravityLocal * (GravityLocal * Horizontal2 + 2 * Delta.Y * Speed2)
			if Discriminant < 0 then
				return nil
			end
			local Denominator = Speed2 - GravityLocal * Delta.Y + math.sqrt(Discriminant)
			if Denominator <= 0 then
				return nil
			end
			local DurationLocal = math.sqrt(2 * Delta:Dot(Delta) / Denominator)
			if DurationLocal <= 0 or DurationLocal > 8 then
				return nil
			end
			local OffsetLocal = Delta + Vector(0, 0.5 * GravityLocal * DurationLocal * DurationLocal, 0)
			return OffsetLocal.Unit, TargetLocal
		end
		if GravityLocal == 0 and Acceleration.Magnitude < 0.001 then
			return A0Features.SolveLinearIntercept(Vector, OriginLocal, TargetLocal, VelocityLocal, SpeedLocal)
		end
		local Force = Acceleration + Vector(0, GravityLocal, 0)
		local function RequiredLocal(Argument)
			local HalfTime2 = 0.5 * Argument * Argument
			local X = Delta.X + VelocityLocal.X * Argument + Force.X * HalfTime2
			local Y = Delta.Y + VelocityLocal.Y * Argument + Force.Y * HalfTime2
			local Z = Delta.Z + VelocityLocal.Z * Argument + Force.Z * HalfTime2
			return X * X + Y * Y + Z * Z - SpeedLocal * SpeedLocal * Argument * Argument
		end
		local Lower, Upper = 0, nil
		local Limit = math.min(8, math.max(0.5, Delta.Magnitude / SpeedLocal * 3 + 1))
		for IndexLocal = 1, 64 do
			local Probe = Limit * IndexLocal / 64
			if RequiredLocal(Probe) <= 0 then
				Upper = Probe
				break
			end
			Lower = Probe
		end
		if not Upper then
			return nil
		end
		for _ = 1, 18 do
			local Middle = (Lower + Upper) * 0.5
			if RequiredLocal(Middle) > 0 then
				Lower = Middle
			else
				Upper = Middle
			end
		end
		local DurationLocal = (Lower + Upper) * 0.5
		local Impact = TargetLocal
			+ VelocityLocal * DurationLocal
			+ Acceleration * (0.5 * DurationLocal * DurationLocal)
		local OffsetLocal = Impact - OriginLocal + Vector(0, GravityLocal * 0.5 * DurationLocal * DurationLocal, 0)
		if OffsetLocal.Magnitude < 0.001 then
			return nil
		end
		return OffsetLocal.Unit, Impact
	end

	function A0Features.CreateInstantRecovery(Deps)
		local Api = { Character = nil, NextAt = 0, Destroyed = false, Status = "Idle" }
		function Api:Step()
			if self.Destroyed or not Deps.alive() or not Deps.settings().InstantHeal then
				return false
			end
			local PlayerLocal, Now = Deps.player, Deps.clock()
			local CharacterLocal = PlayerLocal.Character
			if not CharacterLocal or not CharacterLocal.Parent then
				return false
			end
			if self.Character ~= CharacterLocal then
				self.Character, self.NextAt = CharacterLocal, 0
			end
			if Now < self.NextAt then
				return false
			end
			self.NextAt = Now + 0.1
			local KnockedLocal = CharacterLocal:GetAttribute("Knocked") == true
				or PlayerLocal:GetAttribute("Knocked") == true
			local HumanoidLocal = CharacterLocal:FindFirstChildOfClass("Humanoid")
			if not KnockedLocal or not HumanoidLocal then
				return false
			end
			if HumanoidLocal.Health ~= HumanoidLocal.MaxHealth then
				HumanoidLocal.Health = HumanoidLocal.MaxHealth
			end
			local SettingsLocal = Deps.settings()
			if not SettingsLocal.AutoFarmSurvivor and not SettingsLocal.AutoFarmAFKTotal then
				if CharacterLocal:GetAttribute("Knocked") == true then
					CharacterLocal:SetAttribute("Knocked", false)
				end
				if PlayerLocal:GetAttribute("Knocked") == true then
					PlayerLocal:SetAttribute("Knocked", false)
				end
			end
			for _, PartLocal in ipairs(CharacterLocal:GetDescendants()) do
				if PartLocal:IsA("BasePart") and not PartLocal.CanCollide then
					PartLocal.CanCollide = true
				end
			end
			self.Status = "Local downed-state recovery applied"
			return true
		end
		function Api:Reset()
			self.Character, self.NextAt = nil, 0
		end
		function Api:Destroy()
			self.Destroyed = true
			self:Reset()
		end
		return Api
	end
	function A0Features.CreateFlee(Deps)
		local NextAtLocal = 0
		return function(CharacterLocal, RootLocal, Enemy, Generators, GetPart, CompletedLocal, Paused, GetPoint)
			if
				not Deps.alive()
				or not Deps.settings().AutoFleeKiller
				or CharacterLocal ~= Deps.player.Character
				or not RootLocal
				or not RootLocal.Parent
			then
				return false
			end
			local Now = Deps.clock()
			if Now < NextAtLocal then
				return false
			end
			local HumanoidLocal = CharacterLocal:FindFirstChildOfClass("Humanoid")
			if not HumanoidLocal or HumanoidLocal.Health <= 0 then
				return false
			end
			local TeamLocal = Deps.player.Team and Deps.player.Team.Name:lower() or ""
			if TeamLocal:find("killer", 1, true) or TeamLocal:find("spectat", 1, true) or TeamLocal == "lobby" then
				return false
			end
			if type(GetPart) ~= "function" then
				GetPart = function(Object)
					return Object:IsA("BasePart") and Object
						or Object.PrimaryPart
						or Object:FindFirstChildWhichIsA("BasePart", true)
				end
			end
			for _, NameLocal in ipairs({ "Knocked", "IsHooked", "IsCarried" }) do
				if CharacterLocal:GetAttribute(NameLocal) == true or Deps.player:GetAttribute(NameLocal) == true then
					return false
				end
			end
			if typeof(Enemy) ~= "Vector3" or (RootLocal.Position - Enemy).Magnitude >= 35 then
				return false
			end
			local Best, DistanceLocal = nil, 60
			for IndexLocal, GeneratorLocal in ipairs(Generators or {}) do
				if IndexLocal > 256 then
					break
				end
				if GeneratorLocal and GeneratorLocal.Parent then
					local SuccessLocal, PartLocal = pcall(GetPart, GeneratorLocal)
					if SuccessLocal and PartLocal and PartLocal.Parent then
						local ValidLocal = true
						if type(CompletedLocal) == "function" then
							local StatusLocal, ValueLocal36 = pcall(CompletedLocal, GeneratorLocal)
							ValidLocal = StatusLocal and not ValueLocal36
						end
						if ValidLocal and type(Paused) == "function" then
							local StatusLocal, ValueLocal36 = pcall(Paused, GeneratorLocal)
							ValidLocal = StatusLocal and not ValueLocal36
						end
						local Separation = (PartLocal.Position - Enemy).Magnitude
						if ValidLocal and Separation > DistanceLocal then
							Best, DistanceLocal = PartLocal, Separation
						end
					end
				end
			end
			if not Best or not Best.Parent or CharacterLocal ~= Deps.player.Character or not Deps.alive() then
				return false
			end
			local Destination = Best.CFrame + Vector3.new(0, 3, 0)
			RootLocal.CFrame = Destination
			RootLocal.AssemblyLinearVelocity = Vector3.zero
			NextAtLocal = Now + 3
			return true
		end
	end
	function A0Features.CreateDBD(Deps)
		local Players, LocalPlayer = Deps.players, Deps.player
		local Workspace, RunService = workspace, game:GetService("RunService")
		local SoundService = game:GetService("SoundService")
		local Runtime = {
			Alive = true,
			DBD = {
				SoundAssets = {},
				HudAssets = {},
				SoundOriginal = setmetatable({}, { __mode = "k" }),
				HudOriginal = setmetatable({}, { __mode = "k" }),
				SoundHooks = setmetatable({}, { __mode = "k" }),
			},
		}
		local API, Owned, Effects = {}, {}, {}
		local Settings = {
			DBD = setmetatable({}, {
				__index = function(_, KeyLocal)
					local Config = Deps.settings()
					if KeyLocal == "SoundsEnabled" then
