		local HudDefs = {
			Healthy = { file = "dbd_hud_healthy.png", url = "https://files.catbox.moe/3d3yth.png" },
			Injured = { file = "dbd_hud_injured.png", url = "https://files.catbox.moe/dj03nn.png" },
			Knocked = { file = "dbd_hud_knocked.png", url = "https://files.catbox.moe/yjkbwq.png" },
			Hooked = { file = "dbd_hud_hooked.png", url = "https://files.catbox.moe/ivumkl.png" },
			Carried = { file = "dbd_hud_carried.png", url = "https://files.catbox.moe/jgozjg.png" },
			Chased = { file = "dbd_hud_chased.png", url = "https://files.catbox.moe/him9yt.png" },
			Gen = { file = "dbd_hud_gen.png", url = "https://files.catbox.moe/731qb0.png" },
		}

		local function ExecutorFunction(NameLocal)
			local Direct = {
				request = request or (syn and syn.request) or (http and http.request),
				http_request = http_request,
				isfile = isfile,
				writefile = writefile,
				getcustomasset = getcustomasset,
				getsynasset = getsynasset,
			}
			if type(Direct[NameLocal]) == "function" then
				return Direct[NameLocal]
			end
			if type(getgenv) == "function" then
				local SuccessLocal, Env = pcall(getgenv)
				if SuccessLocal and type(Env) == "table" and type(Env[NameLocal]) == "function" then
					return Env[NameLocal]
				end
			end
			return type(_G[NameLocal]) == "function" and _G[NameLocal] or nil
		end

		local function RequestBytes(UrlLocal)
			local RequestFn = ExecutorFunction("request") or ExecutorFunction("http_request")

			if RequestFn then
				local SuccessLocal, Result = pcall(RequestFn, {
					Url = UrlLocal,
					Method = "GET",
					Timeout = 5,
				})
				if SuccessLocal and Result then
					local BodyLocal = type(Result) == "string" and Result
						or Result.Body
						or Result.body
						or Result.response

					local StatusLocal = type(Result) == "table"
							and (Result.StatusCode or Result.status_code or Result.Status or 200)
						or 200

					if
						BodyLocal
						and #BodyLocal > 50
						and (StatusLocal == 0 or (StatusLocal >= 200 and StatusLocal < 300))
					then
						return BodyLocal
					end
				end
			end

			local SuccessLocal, BodyLocal = pcall(function()
				return game:HttpGet(UrlLocal, true)
			end)
			if SuccessLocal and BodyLocal and #BodyLocal > 50 then
				return BodyLocal
			end
		end

		local function CacheAsset(Def, Fallback)
			local IsfileFn = ExecutorFunction("isfile")
			local WritefileFn = ExecutorFunction("writefile")
			local GetAssetFn = ExecutorFunction("getcustomasset") or ExecutorFunction("getsynasset")

			if IsfileFn and GetAssetFn then
				local OkExists, Exists = pcall(IsfileFn, Def.file)
				if OkExists and Exists then
					local OkAsset, AssetLocal = pcall(GetAssetFn, Def.file)
					if OkAsset and AssetLocal then
						return AssetLocal
					end
				end
			end

			if WritefileFn and GetAssetFn then
				local BodyLocal = RequestBytes(Def.url)
				if BodyLocal and #BodyLocal > 50 then
					pcall(WritefileFn, Def.file, BodyLocal)
					if IsfileFn then
						local OkExists, Exists = pcall(IsfileFn, Def.file)
						if OkExists and Exists then
							local OkAsset, AssetLocal = pcall(GetAssetFn, Def.file)
							if OkAsset and AssetLocal then
								return AssetLocal
							end
						end
					else
						local OkAsset, AssetLocal = pcall(GetAssetFn, Def.file)
						if OkAsset and AssetLocal then
							return AssetLocal
						end
					end
				end
			end

			return Fallback or Def.fallback
		end

		local function SoundCacheCount()
			local Count = 0
			for NameLocal in pairs(SoundDefs) do
				if Runtime.DBD.SoundAssets[NameLocal] then
					Count += 1
				end
			end
			return Count
		end

		local function HudCacheCount()
			local Count = 0
			for NameLocal in pairs(HudDefs) do
				if Runtime.DBD.HudAssets[NameLocal] then
					Count += 1
				end
			end
			return Count
		end

		local DownloadBusy = { sound = false, hud = false }
		local LastDownload = { sound = -math.huge, hud = -math.huge }
		local function DownloadLocal(KindLocal, Defs, AssetsLocal, Count, Force)
			if not Runtime.Alive or not Deps.alive() or DownloadBusy[KindLocal] then
				return Count()
			end
			if not Force and os.clock() - LastDownload[KindLocal] < 30 then
				return Count()
			end
			DownloadBusy[KindLocal] = true
			local Listeners = KindLocal == "sound" and (_G.VD_DBD_Listeners or {}) or (_G.VD_DBD_HUD_Listeners or {})
			local Total, DoneLocal = 0, 0
			for _ in pairs(Defs) do
				Total += 1
			end
			local SuccessLocal, Reason = pcall(function()
				for NameLocal, Def in pairs(Defs) do
					if not Runtime.Alive or not Deps.alive() then
						break
					end
					if not AssetsLocal[NameLocal] then
						local AssetLocal = CacheAsset(Def, Def.fallback)
						if not Runtime.Alive or not Deps.alive() then
							break
						end
						if AssetLocal then
							AssetsLocal[NameLocal] = AssetLocal
						end
					end
					DoneLocal += 1
					for _, Listener in ipairs(Listeners) do
						pcall(Listener, DoneLocal / Total, "Assets: " .. Count() .. "/" .. Total)
					end
					task.wait()
				end
			end)
			LastDownload[KindLocal] = os.clock()
			DownloadBusy[KindLocal] = false
			API.LastError = not SuccessLocal and tostring(Reason) or nil
			local ReadyLocal = Count()
			for _, Listener in ipairs(Listeners) do
				pcall(Listener, ReadyLocal / Total, "Assets: " .. ReadyLocal .. "/" .. Total)
			end
			return ReadyLocal
		end
		API.DownloadAllDBDSounds = function(Force)
			return DownloadLocal("sound", SoundDefs, Runtime.DBD.SoundAssets, SoundCacheCount, Force == true)
		end
		API.DownloadAllDBDHud = function(Force)
			return DownloadLocal("hud", HudDefs, Runtime.DBD.HudAssets, HudCacheCount, Force == true)
		end

		local EffectTimes = {}
		local function PlayDBDEffectLocal(NameLocal, VolumeLocal)
			if not Runtime.Alive or not Deps.alive() then
				return false
			end
			NameLocal = tostring(NameLocal or "Warning")
			local Now = os.clock()
			if EffectTimes[NameLocal] and Now - EffectTimes[NameLocal] < 0.05 then
				return false
			end
			EffectTimes[NameLocal] = Now

			if not Runtime.DBD.SoundAssets[NameLocal] then
				API.DownloadAllDBDSounds()
			end
			if not Runtime.Alive or not Deps.alive() then
				return false
			end

			local Def = SoundDefs[NameLocal]
			local AssetLocal = Runtime.DBD.SoundAssets[NameLocal] or (Def and Def.fallback)
			if not AssetLocal then
				return false
			end

			local Sound = Instance.new("Sound")
			Sound.Name = "UNIQUE_DBD_FX_" .. NameLocal
			Sound.SoundId = AssetLocal
			Sound.Volume = tonumber(VolumeLocal) or Settings.DBD.SoundsVolume or 1
			Sound.Parent = SoundService
			Effects[Sound] = true

			pcall(function()
				Sound:Play()
			end)

			task.delay(8, function()
				if Sound and Sound.Parent then
					Sound:Destroy()
					Effects[Sound] = nil
				end
			end)

			return true
		end

		local SoundIdMap = {
			["84082802102438"] = "Warning",
			["87743901501619"] = "Great",
			["109250612395512"] = "Confirm",
			["108630192794160"] = "HookPoint",
			["78575114991208"] = "HookHit",
			["102000788089804"] = "PalletDrop",
			["90802467356489"] = "ExitReady",
			["97406178741226"] = "GenExplode",
			["123265859114838"] = "GateOpen",
			["124429695332529"] = "GenDone",
		}

		local function ClassifyDBDSound(Sound)
			if not Sound or not Sound:IsA("Sound") then
				return nil
			end
			if string.find(Sound.Name, "UNIQUE_DBD_FX_", 1, true) then
				return nil
			end

			local ValueLocal36 = tostring(Sound.SoundId or "")
			for Number4, Category in pairs(SoundIdMap) do
				if string.find(ValueLocal36, Number4, 1, true) then
					return Category
				end
			end

			local NameLocal = string.lower(tostring(Sound.Name or ""))
			local ParentName = string.lower(Sound.Parent and Sound.Parent.Name or "")
			local PathLocal = ParentName .. "/" .. NameLocal

			if
				(NameLocal == "sound" and PathLocal:find("skillcheck", 1, true))
				or NameLocal:find("warn", 1, true)
				or NameLocal:find("alert", 1, true)
			then
				return "Warning"
			end
			if NameLocal == "great" or NameLocal:find("perfect", 1, true) then
				return "Great"
			end
			if NameLocal == "confirm" or NameLocal:find("good", 1, true) or NameLocal:find("success", 1, true) then
				return "Confirm"
			end
			if (NameLocal == "done" or NameLocal:find("complete", 1, true)) and ParentName == "hitbox" then
				return "GenDone"
			end
			if NameLocal == "burn" and ParentName == "hitbox" then
				return "GenExplode"
			end
			if PathLocal:find("hookpoint", 1, true) then
				return "HookPoint"
			end
			if PathLocal:find("hook", 1, true) then
				return "HookHit"
			end
			if PathLocal:find("pallet", 1, true) then
				return "PalletDrop"
			end
			if PathLocal:find("gate", 1, true) then
				return "GateOpen"
			end
			if PathLocal:find("skillcheck", 1, true) then
				return "Warning"
			end

			return nil
		end

		local function HookDBDSoundLocal(Sound)
			if not Runtime.Alive or not Deps.alive() or not Settings.DBD.SoundsEnabled then
				return false
			end
			if not Sound or not Sound:IsA("Sound") then
				return false
			end
			if Runtime.DBD.SoundHooks[Sound] then
				return true
			end

			local Category = ClassifyDBDSound(Sound)
			if not Category then
				return false
			end

			Runtime.DBD.SoundOriginal[Sound] = Sound.Volume

			local function TriggerLocal()
				if not Runtime.Alive or not Deps.alive() or not Settings.DBD.SoundsEnabled then
					return
				end
				if
					not Settings.DBD.SkillcheckSounds
					and (Category == "Warning" or Category == "Great" or Category == "Confirm")
				then
					return
				end

				pcall(function()
					if Sound.Volume > 0 then
						Sound.Volume = 0
					end
				end)

				PlayDBDEffectLocal(Category, Settings.DBD.SoundsVolume)
			end

			local ConnectionsLocal = {}

			pcall(function()
				table.insert(ConnectionsLocal, Sound.Played:Connect(TriggerLocal))
			end)

			pcall(function()
				table.insert(
					ConnectionsLocal,
					Sound:GetPropertyChangedSignal("Volume"):Connect(function()
						if Runtime.Alive and Deps.alive() and Settings.DBD.SoundsEnabled and Sound.Volume > 0 then
							Sound.Volume = 0
						end
					end)
				)
			end)

			pcall(function()
				table.insert(
					ConnectionsLocal,
					Sound.Destroying:Connect(function()
						Runtime.DBD.SoundHooks[Sound], Runtime.DBD.SoundOriginal[Sound] = nil, nil
						for _, ConnectionLocal in ipairs(ConnectionsLocal) do
							pcall(function()
								ConnectionLocal:Disconnect()
							end)
						end
					end)
				)
			end)
			Runtime.DBD.SoundHooks[Sound] = ConnectionsLocal

			if Settings.DBD.SoundsEnabled and Sound.Playing then
				TriggerLocal()
			end

			return true
		end

		local function RestoreDBDSoundsLocal()
			for Sound, ConnectionsLocal in pairs(Runtime.DBD.SoundHooks) do
				for _, ConnectionLocal in ipairs(ConnectionsLocal) do
					pcall(function()
						ConnectionLocal:Disconnect()
					end)
				end
				Runtime.DBD.SoundHooks[Sound] = nil
			end
			for Sound, VolumeLocal in pairs(Runtime.DBD.SoundOriginal) do
				if Sound and Sound.Parent then
					pcall(function()
						Sound.Volume = VolumeLocal
					end)
				end
			end
			Runtime.DBD.SoundOriginal = setmetatable({}, { __mode = "k" })
		end

		local function ApplyDBDSoundsLocal()
			if not Settings.DBD.SoundsEnabled then
				RestoreDBDSoundsLocal()
				return
			end

			if SoundCacheCount() < 5 then
				API.DownloadAllDBDSounds()
			end

			local Roots = {
				Workspace,
				SoundService,
				LocalPlayer:FindFirstChildOfClass("PlayerGui"),
			}

			for _, RootLocal in ipairs(Roots) do
				if RootLocal then
					for IndexLocal, Object in ipairs(RootLocal:GetDescendants()) do
						if IndexLocal % 64 == 0 then
							task.wait()
							if not Runtime.Alive or not Deps.alive() or not Settings.DBD.SoundsEnabled then
								return
							end
						end
						if Object:IsA("Sound") then
							HookDBDSoundLocal(Object)
						end
					end
				end
			end
		end

		local function StateForPlayer(PlayerLocal)
			if not PlayerLocal then
				return "Healthy"
			end

			local CharacterLocal = PlayerLocal.Character

			if
				PlayerLocal:GetAttribute("IsCarried") == true
				or (CharacterLocal and CharacterLocal:GetAttribute("IsCarried") == true)
			then
				return "Carried"
			end

			if
				PlayerLocal:GetAttribute("IsHooked") == true
				or (CharacterLocal and CharacterLocal:GetAttribute("IsHooked") == true)
			then
				return "Hooked"
			end

			local KnockedLocal = PlayerLocal:GetAttribute("Knocked") == true
				or PlayerLocal:GetAttribute("IsKnocked") == true
				or (
					CharacterLocal
					and (
						CharacterLocal:GetAttribute("Knocked") == true
						or CharacterLocal:GetAttribute("IsKnocked") == true
					)
				)

			if CharacterLocal then
				local HumanoidLocal = CharacterLocal:FindFirstChildOfClass("Humanoid")
				if HumanoidLocal and HumanoidLocal.Health <= 0 then
					KnockedLocal = true
				end
			end

			if KnockedLocal then
				return "Knocked"
			end

			if
				PlayerLocal:GetAttribute("IsChased") == true
				or (CharacterLocal and CharacterLocal:GetAttribute("IsChased") == true)
			then
				return "Chased"
			end

			local InjuredLocal = PlayerLocal:GetAttribute("Injured") == true
				or PlayerLocal:GetAttribute("IsInjured") == true
				or (
					CharacterLocal
					and (
						CharacterLocal:GetAttribute("Injured") == true
						or CharacterLocal:GetAttribute("IsInjured") == true
					)
				)

			if not InjuredLocal and CharacterLocal then
				local HumanoidLocal = CharacterLocal:FindFirstChildOfClass("Humanoid")
				if HumanoidLocal and HumanoidLocal.MaxHealth > 0 and HumanoidLocal.Health < HumanoidLocal.MaxHealth then
					InjuredLocal = true
				end
			end

			return InjuredLocal and "Injured" or "Healthy"
		end

		local function SurvivorPlayers()
			local ListLocal = {}

			for _, PlayerLocal in ipairs(Players:GetPlayers()) do
				local TeamName = PlayerLocal.Team and string.lower(PlayerLocal.Team.Name) or ""
				local Role = tostring(PlayerLocal:GetAttribute("Role") or "")
				local IsKiller = TeamName:find("killer", 1, true)
					or Role == "Killer"
					or PlayerLocal:GetAttribute("IsKiller") == true

				local Spectator = TeamName:find("spectat", 1, true) or TeamName == "lobby"

				if not IsKiller and not Spectator then
					table.insert(ListLocal, PlayerLocal)
				end
			end

			table.sort(ListLocal, function(Argument, Argument1)
				return Argument.Name < Argument1.Name
			end)

			return ListLocal
		end

		local function ResolveRowPlayer(RowLocal, LabelLocal, Survivors)
			local TextLocal3 = LabelLocal and tostring(LabelLocal.Text or "") or ""
			TextLocal3 = TextLocal3:gsub("^%s+", ""):gsub("%s+$", "")

			local Attributed = RowLocal:GetAttribute("Player")
				or RowLocal:GetAttribute("Username")
				or RowLocal:GetAttribute("SurvivorName")

			if type(Attributed) == "string" and Attributed ~= "" then
				TextLocal3 = Attributed
			end

			if TextLocal3 ~= "" then
				local Wanted = string.lower(TextLocal3)
				for _, PlayerLocal in ipairs(Players:GetPlayers()) do
					local Username = string.lower(PlayerLocal.Name)
					local DisplayLocal = string.lower(PlayerLocal.DisplayName)
					if
						Wanted == Username
						or Wanted == DisplayLocal
						or string.find(Wanted, Username, 1, true)
						or string.find(Wanted, DisplayLocal, 1, true)
						or string.find(Username, Wanted, 1, true)
						or string.find(DisplayLocal, Wanted, 1, true)
					then
						return PlayerLocal
					end
				end
			end

			local IndexLocal = tonumber(RowLocal.Name:match("%d+"))
			return IndexLocal and Survivors[IndexLocal] or nil
		end

		local function SetHudImage(ImageLocal, AssetLocal)
			if not ImageLocal or not AssetLocal then
				return
			end
			if Runtime.DBD.HudOriginal[ImageLocal] == nil then
				Runtime.DBD.HudOriginal[ImageLocal] = ImageLocal.Image
			end
			if ImageLocal.Image ~= AssetLocal then
				ImageLocal.Image = AssetLocal
			end
		end

		local function RestoreDBDHudLocal()
			for ImageLocal, OriginalImage in pairs(Runtime.DBD.HudOriginal) do
				if ImageLocal and ImageLocal.Parent then
					pcall(function()
						ImageLocal.Image = OriginalImage
					end)
				end
			end
			Runtime.DBD.HudOriginal = setmetatable({}, { __mode = "k" })
		end

		local function UpdateDBDHudLocal()
			if not Runtime.Alive or not Deps.alive() or not Settings.DBD.HudEnabled then
				RestoreDBDHudLocal()
				return
			end

			if HudCacheCount() < 7 then
				API.DownloadAllDBDHud()
			end
			if not Runtime.Alive or not Deps.alive() or not Settings.DBD.HudEnabled then
				return
			end

			local PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
			if not PlayerGui then
				return
			end

			local GameGuis = {}
			local Known = {
				"Survivor",
				"Survivor-mob",
				"Survivor-mo",
				"Slasher",
				"Slasher-mob",
				"Slasher-mo",
				"Killer",
				"Killer-mob",
				"Killer-mo",
			}

			for _, NameLocal in ipairs(Known) do
				local GuiLocal = PlayerGui:FindFirstChild(NameLocal)
				if GuiLocal and not table.find(GameGuis, GuiLocal) then
					table.insert(GameGuis, GuiLocal)
				end
			end

			for _, GuiLocal in ipairs(PlayerGui:GetChildren()) do
				if GuiLocal:IsA("ScreenGui") and not table.find(GameGuis, GuiLocal) then
					local Lower = string.lower(GuiLocal.Name)
					if
						Lower:find("survivor", 1, true)
						or Lower:find("slasher", 1, true)
						or Lower:find("killer", 1, true)
					then
						table.insert(GameGuis, GuiLocal)
					end
				end
			end

			local Survivors = SurvivorPlayers()

			for _, GuiLocal in ipairs(GameGuis) do
				local GenLocal = GuiLocal:FindFirstChild("Gen") or GuiLocal:FindFirstChild("Generators")
				local Holder = GenLocal
					and (
						GenLocal:FindFirstChild("genholder")
						or GenLocal:FindFirstChild("GenHolder")
						or GenLocal:FindFirstChild("Holder")
					)

				local GenImage = (
					Holder
					and (Holder:FindFirstChild("ImageLabel") or Holder:FindFirstChildWhichIsA("ImageLabel", true))
				) or (GenLocal and GenLocal:FindFirstChildWhichIsA("ImageLabel", true))

				if GenImage and Runtime.DBD.HudAssets.Gen then
					SetHudImage(GenImage, Runtime.DBD.HudAssets.Gen)
				end

				local RowsLocal = {}
				local FrameLocal = GuiLocal:FindFirstChild("Frame")
					or GuiLocal:FindFirstChild("Survivors")
					or GuiLocal:FindFirstChild("SurvivorsFrame")

				if FrameLocal then
					for _, RowLocal in ipairs(FrameLocal:GetChildren()) do
						if
							RowLocal:IsA("GuiObject")
							and (
								string.find(string.lower(RowLocal.Name), "survivor", 1, true)
								or RowLocal:FindFirstChildWhichIsA("TextLabel", true)
								or RowLocal:FindFirstChildWhichIsA("ImageLabel", true)
							)
						then
							table.insert(RowsLocal, RowLocal)
						end
					end
				end

				if #RowsLocal == 0 then
					for _, RowLocal in ipairs(GuiLocal:GetDescendants()) do
						if RowLocal:IsA("GuiObject") then
							local Lower = string.lower(RowLocal.Name)
							if Lower:match("survivor%d+") or Lower == "survivor" then
								table.insert(RowsLocal, RowLocal)
							end
						end
					end
				end

				for _, RowLocal in ipairs(RowsLocal) do
					local LabelLocal = RowLocal:FindFirstChild("TextLabel")
						or RowLocal:FindFirstChildWhichIsA("TextLabel", true)

					local ImageLocal = RowLocal:FindFirstChild("ImageLabel")
						or RowLocal:FindFirstChildWhichIsA("ImageLabel", true)

					if ImageLocal then
						local PlayerLocal = ResolveRowPlayer(RowLocal, LabelLocal, Survivors)
						if PlayerLocal then
							local StateLocal = StateForPlayer(PlayerLocal)
							local AssetLocal = Runtime.DBD.HudAssets[StateLocal]
							if AssetLocal then
								SetHudImage(ImageLocal, AssetLocal)
							end
						end
					end
				end
			end
		end

