		local HudQueued = false
		ScheduleHud = function()
			if HudQueued or not Runtime.Alive or not Deps.alive() then
				return
			end
			HudQueued = true
			task.defer(function()
				HudQueued = false
				if Runtime.Alive and Deps.alive() then
					UpdateDBDHudLocal()
				end
			end)
		end
		TrackLocal(Workspace.DescendantAdded:Connect(function(Object)
			if Runtime.Alive and Deps.alive() and Settings.DBD.SoundsEnabled and Object:IsA("Sound") then
				task.defer(function()
					HookDBDSoundLocal(Object)
				end)
			end
		end))

		local PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if PlayerGui then
			TrackLocal(PlayerGui.DescendantAdded:Connect(function(Object)
				if Runtime.Alive and Deps.alive() and Settings.DBD.SoundsEnabled and Object:IsA("Sound") then
					task.defer(function()
						HookDBDSoundLocal(Object)
					end)
				end

				if
					Runtime.Alive
					and Deps.alive()
					and Settings.DBD.HudEnabled
					and (Object:IsA("ImageLabel") or Object:IsA("ImageButton") or Object:IsA("GuiObject"))
				then
					ScheduleHud()
				end
			end))
		end

		TrackLocal(SoundService.DescendantAdded:Connect(function(Object)
			if Runtime.Alive and Deps.alive() and Settings.DBD.SoundsEnabled and Object:IsA("Sound") then
				task.defer(function()
					HookDBDSoundLocal(Object)
				end)
			end
		end))

		local ExitReadyPlayed = false
		local TimerAccumulator = 0

		TrackLocal(RunService.Heartbeat:Connect(function(DeltaTime)
			if not Runtime.Alive or not Deps.alive() then
				return
			end
			TimerAccumulator += DeltaTime or 0
			if TimerAccumulator < 0.25 then
				return
			end
			TimerAccumulator = 0
			if Settings.DBD.HudEnabled then
				ScheduleHud()
			end

			if Settings.DBD.SoundsEnabled then
				local PlayerGui1 = LocalPlayer:FindFirstChildOfClass("PlayerGui")
				local SurvivorLocal = PlayerGui1 and PlayerGui1:FindFirstChild("Survivor")
				local TimeFrame = SurvivorLocal and SurvivorLocal:FindFirstChild("time")
				local Timer = TimeFrame and TimeFrame:FindFirstChild("TimerLabel")

				if Timer and Timer:IsA("TextLabel") then
					local ValueLocal36 = tostring(Timer.Text):gsub("%s+", "")
					if ValueLocal36 == "2:00" or ValueLocal36 == "02:00" then
						if not ExitReadyPlayed then
							ExitReadyPlayed = true
							PlayDBDEffectLocal("ExitReady", Settings.DBD.SoundsVolume)
						end
					elseif ValueLocal36 ~= "1:59" then
						ExitReadyPlayed = false
					end
				end
			else
				ExitReadyPlayed = false
			end
		end))
		function API.Destroy()
			if not Runtime.Alive then
				return
			end
			Runtime.Alive = false
			for _, ConnectionLocal in ipairs(Owned) do
				pcall(function()
					ConnectionLocal:Disconnect()
				end)
			end
			table.clear(Owned)
			RestoreDBDSoundsLocal()
			RestoreDBDHudLocal()
			for Sound in pairs(Effects) do
				pcall(function()
					Sound:Destroy()
				end)
			end
			table.clear(Effects)
		end
		return API
	end

	function A0Features.CreateGeneratorBuff(Deps)
		local Api = { Busy = false, Destroyed = false, Generation = 0, Started = {}, Remote = nil, Status = "Idle" }
		function Api:Stop(Reason)
			self.Generation += 1
			local RemoteLocal = self.Remote
			for PointLocal in pairs(self.Started) do
				if RemoteLocal then
					pcall(function()
						RemoteLocal:FireServer(PointLocal, false)
					end)
				end
			end
			table.clear(self.Started)
			self.Busy, self.Remote = false, nil
			if Reason then
				self.Status = Reason
			end
		end
		function Api:Run()
			if self.Destroyed or not Deps.alive() or self.Busy then
				return false
			end
			local CharacterLocal = Deps.player.Character
			local RootLocal = CharacterLocal and CharacterLocal:FindFirstChild("HumanoidRootPart")
			if not RootLocal then
				self.Status = "Character root unavailable"
				return false
			end
			local Candidates, Seen = {}, {}
			local function AddLocal(Object)
				if Object and Object.Parent and not Seen[Object] then
					Seen[Object] = true
					Candidates[#Candidates + 1] = Object
				end
			end
			for IndexLocal, Object in ipairs(Deps.generators() or {}) do
				if IndexLocal > 256 then
					break
				end
				AddLocal(Object)
			end
			local Map = Deps.world:FindFirstChild("Map")
			if Map then
				for _, NameLocal in ipairs({ "Generators", "Gens" }) do
					local FolderLocal = Map:FindFirstChild(NameLocal)
					if FolderLocal then
						for IndexLocal, Object in ipairs(FolderLocal:GetChildren()) do
							if IndexLocal > 256 then
								break
							end
							if Object.Name:lower():find("generator", 1, true) then
								AddLocal(Object)
							end
						end
					end
				end
			end
			local TargetLocal, Best = nil, 30
			for _, Object in ipairs(Candidates) do
				local PartLocal = Object:IsA("BasePart") and Object
					or Object.PrimaryPart
					or Object:FindFirstChildWhichIsA("BasePart", true)
				if PartLocal then
					local DistanceLocal = (PartLocal.Position - RootLocal.Position).Magnitude
					if DistanceLocal <= Best then
						TargetLocal, Best = Object, DistanceLocal
					end
				end
			end
			if not TargetLocal then
				self.Status = "No generator within 30 studs"
				return false
			end
			local Points = {}
			for _, Object in ipairs(TargetLocal:GetChildren()) do
				if Object.Name:lower():find("point", 1, true) then
					Points[#Points + 1] = Object
				end
			end
			table.sort(Points, function(Argument, Argument1)
				return Argument.Name < Argument1.Name
			end)
			local RemoteLocal = Deps.remote()
			if not RemoteLocal or #Points == 0 or #Points > 16 then
				self.Status = "Repair remote or supported point layout unavailable"
				return false
			end
			self.Busy, self.Remote = true, RemoteLocal
			self.Generation += 1
			local GenerationLocal = self.Generation
			local function CurrentLocal()
				return not self.Destroyed
					and self.Generation == GenerationLocal
					and Deps.alive()
					and Deps.player.Character == CharacterLocal
					and RootLocal.Parent
					and TargetLocal.Parent
			end
			local function Send(PointLocal, ValueLocal36)
				if not CurrentLocal() or not PointLocal.Parent then
					error("Generator action cancelled")
				end
				RemoteLocal:FireServer(PointLocal, ValueLocal36)
				self.Started[PointLocal] = ValueLocal36 and true or nil
			end
			Deps.spawn(function()
				if not CurrentLocal() then
					if self.Generation == GenerationLocal then
						self:Stop("Character changed")
					end
					return
				end
				local SuccessLocal, Reason = pcall(function()
					if #Points == 2 then
						Send(Points[2], true)
						Deps.yield(0.2)
						Send(Points[1], true)
						Deps.yield(0.2)
						Send(Points[1], false)
					elseif #Points > 2 then
						local LastLocal = Points[#Points]
						for IndexLocal = 1, #Points - 1 do
							Send(Points[IndexLocal], true)
							Deps.yield(0.2)
							Send(LastLocal, true)
							Deps.yield(0.2)
							Send(LastLocal, false)
							if IndexLocal < #Points - 1 then
								Deps.yield(0.2)
							end
						end
					else
						Send(Points[1], true)
						Deps.yield(0.2)
						Send(Points[1], false)
					end
				end)
				if self.Generation ~= GenerationLocal then
					return
				end
				if not SuccessLocal then
					self:Stop("Generator request failed: " .. tostring(Reason))
					return
				end
				self.Busy = false
				self.Status = "Generator buff sequence sent; server outcome not verified"
			end)
			return true
		end
		function Api:Destroy()
			self.Destroyed = true
			self:Stop("Session stopped")
		end
		return Api
	end

