					if ActionsLocal and type(ActionsLocal.InstantEscape) == "function" then
						local CharacterLocal = localPlayer.Character
						local RootLocal = CharacterLocal and CharacterLocal:FindFirstChild("HumanoidRootPart")
						if RootLocal then
							ActionsLocal.InstantEscape(RootLocal, showNotification)
							return true
						end
					end
					return A0Features.Escape({
						character = function()
							return localPlayer.Character
						end,
						alive = function()
							return ActiveLoop and not UiLibrary.Destroyed
						end,
						world = workspace,
						yield = task.wait,
						stopInteractions = _G.VD_StopAllInteractions,
					})
				end)
				A0Features.EscapeBusy = false
				if not ActiveLoop or UiLibrary.Destroyed then
