						or not TargetLocal.Parent
						or not PartLocal.Parent
						or (RootLocal.Position - PartLocal.Position).Magnitude > 7
					then
						break
					end
					local RequestedLocal = false

					if Attempt > 1 and A0Features.Input then
						RequestedLocal = A0Features.Input:Pumpkin()
					end
					if not RequestedLocal and RemoteLocal then
						RequestedLocal = pcall(function()
							RemoteLocal:FireServer(HB)
						end)
					end
					if not RequestedLocal and A0Features.Input then
						RequestedLocal = A0Features.Input:Pumpkin()
					end
					if not RequestedLocal then
						ReportLocal("Pumpkin remote / visible action unavailable")
						break
					end
					ReportLocal("Pumpkin crush requested; waiting for replication")
					task.wait(0.35)
				end
				if TargetLocal.Parent and TargetLocal:IsDescendantOf(workspace) then
					CooldownLocal[TargetLocal] = tick() + 15
				else
					WorldLocal:Remove(TargetLocal)
					removeModelESP(TargetLocal, "Pumpkins")
					ReportLocal("Pumpkin removed from world")
				end
			end)
			BusyLocal = false
			if not SuccessLocal then
				ReportLocal("Pumpkin action failed")
				warn("A0 | pumpkins: " .. tostring(ErrorLocal))
			end
		end
		Farm:Button({
			Text = "Crush Nearest Pumpkin",
			Flag = false,
			Callback = function()
				Collect(true)
			end,
		})
		Farm:Button({
			Text = "Stop Pumpkin Automation",
			Flag = false,
			Callback = function()
				SettingsLocal1.AutoPumpkin = false
				Nav:Cancel()
				PumpkinToggle:Set(false, true)
				pcall(saveSettings)
				ReportLocal("Stopped")
			end,
		})
		local Aim = __tabFor(tabCombat):Section("Twist of Fate Prediction", 1)
		ToggleLocal(Aim, "RevolverSilentAim.Prediction", "Predict Twist of Fate Movement")
		SliderLocal(Aim, "RevolverSilentAim.ProjectileSpeed", "Twist of Fate Projectile Speed", 100, 1500)
		Aim:Label("500 studs/s is the secondary reference default; verify it in your game.", { Style = "dim" })
		__A0Boot:SpawnJob("Indexing pumpkins, traps and bots…", function()
			assert(Rescan(), "Updated world index failed")
		end)
		registerConnection(RunService.RenderStepped:Connect(function()
			if __A0Boot.Accepted then
				A0Features.Trap:Step()
			end
		end))
		task.spawn(function()
			if not __A0Boot:AwaitRelease() then
				return
			end
			while AliveLocal() do
				if SettingsLocal1.AutoPumpkin then
					Collect(false)
				end
				task.wait(SettingsLocal1.AutoPumpkin and 0.25 or 0.75)
			end
		end)
		local OldReport = A0Features.Report
		A0Features.Report = function()
			return OldReport()
				.. "\nPumpkins: "
				.. StatusLocal
				.. "\nNavigation: "
				.. Nav.Status
				.. "\nBear Trap: "
				.. A0Features.Trap.Status
				.. "\nReference-only features without local implementations remain unavailable."
		end
		_G.A0FeatureReport = A0Features.Report
		UiLibrary:OnUnload(function()
			A0Features.Trap:Destroy()
			Nav:Destroy()
			A0Features.FarmPresentation:Destroy()
			WorldLocal:Destroy()
			for Object in pairs(ActiveESP.Pumpkins) do
				removeModelESP(Object, "Pumpkins")
			end
			for Object in pairs(ActiveESP.BearTraps) do
				removeModelESP(Object, "BearTrap")
			end
		end)
	end)()

	__A0Boot:Phase("Preparing search and final layout…")
	__A0Boot:Budget()

	__A0Boot:Budget()
	__A0Boot:Done("search", "Search index ready")
	__A0Boot:SpawnJob("Preparing map cache…", function()
		scanMapObjects()
		while __mapScanBusy do
			__A0Boot:Check()
			RunService.Heartbeat:Wait()
		end
		if __mapScanError then
			error("Initial map scan failed: " .. __mapScanError)
		end
		__A0Boot:Done("map", "Map cache ready")
	end)
	__A0Boot.Finalize = function()
		A0Features.Layout:Apply()
		if __A0Boot.ESPRefreshDirty then
			__A0Boot.ESPRefreshDirty = false
			__A0Boot.FlushESP = true
			local SuccessLocal, MessageLocal = pcall(ValueLocal30)
			__A0Boot.FlushESP = false
			if not SuccessLocal then
				error(MessageLocal)
			end
		end
		__A0Boot:Phase("Checking every tab and final layout…")
		local Expected = {
			tabESP,
			tabMovement,
			tabInteractables,
			tabKiller,
			tabCombat,
			tabVisuals,
			tabMisc,
			tabAnimations,
			tabConfig,
		}
		assert(#LibraryWindow.Tabs == #Expected, "A0 startup: expected nine tabs")
		for IndexLocal = 1, 9 do
			local PageLocal = Expected[IndexLocal]
			assert(PageLocal, "A0 startup: required tab " .. IndexLocal .. " missing")
			__A0Boot:Check()
			local TabLocal = __pageTabs[PageLocal]
			assert(
				TabLocal and TabLocal.Page and TabLocal.Page.Parent and TabLocal.Button and TabLocal.Button.Parent,
				"A0 startup: tab " .. IndexLocal .. " incomplete"
			)
			local NavigationLocal = LibraryWindow.TabStyle == "dock" and TabLocal.Slot or TabLocal.Button
			assert(
				NavigationLocal and NavigationLocal.Parent == LibraryWindow.TabBar,
				"A0 startup: missing tab navigation " .. tostring(TabLocal.Name)
			)
			local Sections = 0
			for _, ColumnLocal in ipairs(TabLocal.Columns) do
				Sections += ColumnLocal.Order or 0
			end
			assert(Sections > 0, "A0 startup: empty tab " .. tostring(TabLocal.Name))
		end
		__balanceSectionColumns()
		LibraryWindow:RefreshDockLayout()

		RunService.Heartbeat:Wait()
		__A0Boot:Check()
		LibraryWindow:RefreshDockLayout()
		local SidebarWidth = LibraryWindow.TabBar.Size.X.Offset
		assert(SidebarWidth >= 100, "A0 startup: left tab sidebar has no usable width")
		__A0Boot:Done("layout", "All nine tabs validated")
	end
	__A0Boot.OnReveal = function()
		if UiLibrary.Destroyed or not LibraryWindow.Gui.Parent then
			error("A0 window was unloaded during startup")
		end
		ValueLocal13 = false
		LibraryWindow.Gui.Enabled = true
		if FloatingHeaderGui and FloatingHeaderGui.Parent then
			FloatingHeaderGui.Enabled = true
		end
		toggleUI(true)
	end
end
task.spawn(function()
	__A0Boot:Run(__A0Initialize)
end)
